from jsonb_array_elements($j$[{"id":"A-W0-BASELINE-S1","version":1,"title":"Why Do Leaves Change Colour? (bài đọc baseline)","url":null,"author":"Tự soạn cho Pilot Kit A v0.2.1 (phụ huynh/Claude); không phải trích từ sách hay đề thi","rights_note":"Tự soạn, không sao chép. Đã đối chiếu (kit mục 2.11): USDA Forest Service (https://fs.usda.gov/Internet/FSE_DOCUMENTS/stelprd3817419.pdf); RSC (https://edu.rsc.org/everyday-chemistry/the-chemistry-behind-leaves-changing-colour-and-falling-from-trees/4018155.article); Britannica (https://britannica.com/story/why-do-leaves-fall-in-autumn); câu cây bàng Hà Nội lá đỏ vào mùa đông: VietNamNet (https://vietnamnet.vn/ngam-ha-noi-dep-nhu-tranh-trong-mua-la-bang-do-ruc-214928.html).","modality":"text","body":"Why Do Leaves Change Colour?\n\nIn many countries, green leaves turn yellow, orange or red in autumn, and then they fall. Why does this happen?\n\nA leaf is green because it has a green material called chlorophyll. Chlorophyll helps the tree to make food from sunlight, air and water. In spring and summer, the tree makes a lot of chlorophyll, so the green colour covers the other colours in the leaf.\n\nIn autumn, the days get shorter and the nights get longer. With less sunlight, the tree stops making new chlorophyll. The old chlorophyll slowly breaks down, and the green colour disappears. Now we can see yellow and orange. These colours were in the leaf all summer, but the green colour hid them.\n\nSome trees, like maples, also make a new red colour in autumn. Their leaves are brightest after sunny days and cool nights.\n\nNext, a thin wall grows where the leaf joins the branch, and the leaf falls. Thin leaves full of water could freeze in a cold winter, so the tree drops them.\n\nIn Hanoi, the big leaves of the Indian almond tree (cây bàng) turn red in winter. I think these red leaves are the most beautiful thing in our city.","source_hash":"105b5c269b8a3c58b34d6390fa363523e851b40efae31d1662b20f8620cbf3b9"},{"id":"A-W0-BASELINE-S2","version":1,"title":"How Do Bats Find Food in the Dark? (bài nghe baseline, file A_BL_L)","url":null,"author":"Tự soạn cho Pilot Kit A v0.2.1 (phụ huynh/Claude); không phải trích từ sách hay đề thi","rights_note":"Tự soạn, đọc bằng một giọng TTS cố định, tốc độ 0,9x. Đã đối chiếu: Cleveland Zoological Society (https://www.clevelandzoosociety.org/Z/2024/06/20/ask-the-expert-do-all-bats-use-echolocation), National Geographic 2014 (https://www.nationalgeographic.com/science/phenomena/2014/12/04/fruit-bats-have-sonar-too-but-its-not-very-good/). Chưa kiểm được: \"âm thanh quá cao để người nghe thấy\" và \"thời gian tiếng vang cho biết khoảng cách\" (trang NPS về dơi chưa mở được); phụ huynh kiểm trước 17/10.","modality":"audio","body":null,"source_hash":"bdc149d271ec1749f616a47e22182e79f642fa5ca1383c287e8a92a4c5d0be65"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W0-BASELINE' and it.version = 1 and it.published_at is not null)
on conflict (id, version) do nothing;

insert into english.source_transcripts(source_id, source_version, transcript)
select r->>'id', (r->>'version')::int, r->>'transcript'
from jsonb_array_elements($j$[{"id":"A-W0-BASELINE-S2","version":1,"transcript":"How Do Bats Find Food in the Dark?\n\nHello! Today's question is: how can a bat catch insects at night, when it is too dark to see well?\n\nMany bats use sound. While a bat is flying, it makes very high sounds. Most of these sounds are too high for people to hear. When a sound hits an insect, it bounces back to the bat. This returning sound is called an echo.\n\nThe bat listens to the echo carefully. The echo tells the bat where the insect is. The bat also notices how long the echo takes to come back. This tells it how far away the insect is. Then the bat flies quickly and catches its dinner.\n\nFinding things with echoes like this is called echolocation. But not all bats do it. Some big fruit bats find their food mainly with their eyes and their good sense of smell.\n\nSo next time you see a bat at night, remember: it is listening to the dark!"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W0-BASELINE' and it.version = 1 and it.published_at is not null)
on conflict (source_id, source_version) do nothing;

update english.sources set published_at = now()
where version = 1 and id in ('A-W0-BASELINE-S1', 'A-W0-BASELINE-S2') and published_at is null;

