from jsonb_array_elements($j$[{"step_no":1,"item_id":"BL-R1","kind":"answer","answer":"b","explanation_vi":"Ý chính: lá đổi màu và rụng. Chấm c1 của Đọc hiểu."},{"step_no":1,"item_id":"BL-R2","kind":"sealed","answer":"Make food (from sunlight, air and water).","explanation_vi":"Chi tiết 1/4."},{"step_no":1,"item_id":"BL-R3","kind":"sealed","answer":"There is less sunlight / the days get shorter (the nights get longer).","explanation_vi":"Chi tiết 2/4 (nhân quả có trong bài)."},{"step_no":1,"item_id":"BL-R4","kind":"sealed","answer":"In the leaf already; the green colour hid them.","explanation_vi":"Chi tiết 3/4."},{"step_no":1,"item_id":"BL-R5","kind":"sealed","answer":"B, D, A, C","explanation_vi":"Chi tiết 4/4 (trình tự). Đọc hiểu cần 4/4 chi tiết (80%)."},{"step_no":1,"item_id":"BL-R6","kind":"sealed","answer":"No. The yellow was in the leaf all summer; the green chlorophyll is breaking down, so now the yellow shows.","explanation_vi":"CHẨN ĐOÁN (suy luận, không ghi dòng kỹ năng). Cần nêu dấu hiệu trong bài (\"These colours were in the leaf all summer\")."},{"step_no":1,"item_id":"BL-R7","kind":"sealed","answer":"Covered them so we could not see them (che, giấu).","explanation_vi":"CHẨN ĐOÁN (nghĩa từ theo ngữ cảnh)."},{"step_no":1,"item_id":"BL-R8","kind":"sealed","answer":"(B). It says what the writer feels ('I think', 'the most beautiful') and nobody can check it. (A) can be checked, so it is a fact.","explanation_vi":"CHẨN ĐOÁN (sự thật/ý kiến). Chỉ có 1 câu nên A-T5-FACTOP-R là NULL, không ghi dòng kỹ năng."},{"step_no":1,"item_id":"step-1:note","kind":"note","answer":null,"explanation_vi":"CN 18/10 - Đọc. Không từ điển. Xem lại bài khi trả lời là bình thường của kỹ năng đọc: không ghi source_open (kit mục 1.3). Chấm: câu 1 = ý chính; câu 2-5 = 4 chi tiết (cần 4/4); câu 6-8 chẩn đoán."},{"step_no":2,"item_id":"BL-L1","kind":"answer","answer":"b","explanation_vi":"Ý chính."},{"step_no":2,"item_id":"BL-L2","kind":"sealed","answer":"While it is flying.","explanation_vi":"Chi tiết 1/4."},{"step_no":2,"item_id":"BL-L3","kind":"sealed","answer":"No. They are too high (for people to hear).","explanation_vi":"Chi tiết 2/4."},{"step_no":2,"item_id":"BL-L4","kind":"sealed","answer":"A sound that bounces back / comes back.","explanation_vi":"Chi tiết 3/4."},{"step_no":2,"item_id":"BL-L5","kind":"sealed","answer":"With their eyes and (their sense of) smell.","explanation_vi":"Chi tiết 4/4. Nghe hiểu cần >= 3/4 chi tiết (75%)."},{"step_no":2,"item_id":"BL-L6","kind":"sealed","answer":"Insect A. The time the echo takes to come back tells how far away the insect is; a faster echo means a shorter way.","explanation_vi":"CHẨN ĐOÁN (suy luận khi nghe)."},{"step_no":2,"item_id":"step-2:note","kind":"note","answer":null,"explanation_vi":"CN 18/10 - Nghe. Phát tối đa 2 lần, không cho xem chữ (xem chữ = transcript_open). Chấm: câu 1 = ý chính; câu 2-5 = 4 chi tiết (cần >= 3/4); câu 6 chẩn đoán."},{"step_no":3,"item_id":"BL-V01","kind":"answer","answer":"c","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V02","kind":"answer","answer":"d","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V03","kind":"answer","answer":"e","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V04","kind":"answer","answer":"a","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V05","kind":"answer","answer":"b","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V06","kind":"answer","answer":"h","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V07","kind":"answer","answer":"i","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V08","kind":"answer","answer":"f","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V09","kind":"answer","answer":"j","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V10","kind":"answer","answer":"g","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V11","kind":"answer","answer":"m","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V12","kind":"answer","answer":"n","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V13","kind":"answer","answer":"l","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V14","kind":"answer","answer":"o","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-V15","kind":"answer","answer":"k","explanation_vi":"CHẨN ĐOÁN độ rộng từ vựng (nhận biết _/15)."},{"step_no":3,"item_id":"BL-VB1","kind":"sealed","answer":"Đ nếu đúng nghĩa và đúng dạng từ (vd. The ice cream melted in the sun.); ? nếu câu đúng nhưng không cho thấy nghĩa; S nếu sai.","explanation_vi":"CHẨN ĐOÁN (dùng được _/5). Không ghi dòng kỹ năng."},{"step_no":3,"item_id":"BL-VB2","kind":"sealed","answer":"Đ nếu đúng nghĩa và đúng dạng từ (vd. The ice cream melted in the sun.); ? nếu câu đúng nhưng không cho thấy nghĩa; S nếu sai.","explanation_vi":"CHẨN ĐOÁN (dùng được _/5). Không ghi dòng kỹ năng."},{"step_no":3,"item_id":"BL-VB3","kind":"sealed","answer":"Đ nếu đúng nghĩa và đúng dạng từ (vd. The ice cream melted in the sun.); ? nếu câu đúng nhưng không cho thấy nghĩa; S nếu sai.","explanation_vi":"CHẨN ĐOÁN (dùng được _/5). Không ghi dòng kỹ năng."},{"step_no":3,"item_id":"BL-VB4","kind":"sealed","answer":"Đ nếu đúng nghĩa và đúng dạng từ (vd. The ice cream melted in the sun.); ? nếu câu đúng nhưng không cho thấy nghĩa; S nếu sai.","explanation_vi":"CHẨN ĐOÁN (dùng được _/5). Không ghi dòng kỹ năng."},{"step_no":3,"item_id":"BL-VB5","kind":"sealed","answer":"Đ nếu đúng nghĩa và đúng dạng từ (vd. The ice cream melted in the sun.); ? nếu câu đúng nhưng không cho thấy nghĩa; S nếu sai.","explanation_vi":"CHẨN ĐOÁN (dùng được _/5). Không ghi dòng kỹ năng."},{"step_no":3,"item_id":"step-3:note","kind":"note","answer":null,"explanation_vi":"CN 18/10 - Từ vựng (15 từ). Chẩn đoán độ rộng từ vựng, không ghi dòng kỹ năng."},{"step_no":4,"item_id":"BL-N1","kind":"sealed","answer":"Nói vật gì ngay đầu; >= 4 chi tiết thuộc >= 2 khía cạnh.","explanation_vi":"Chẩn đoán."},{"step_no":4,"item_id":"step-4:note","kind":"note","answer":null,"explanation_vi":"T2 19/10 - N1 Mô tả (45-60 giây). Ghi để cô tham khảo khi chốt bộ kỹ năng; A-L4-DESC-S nằm ngoài bộ 12."},{"step_no":5,"item_id":"BL-N2","kind":"sealed","answer":">= 4 bước đúng thứ tự; từ chỉ trình tự.","explanation_vi":"Chẩn đoán."},{"step_no":5,"item_id":"step-5:note","kind":"note","answer":null,"explanation_vi":"T2 19/10 - N2 Trình tự (45-60 giây). Ghi để cô tham khảo; A-L3-SEQ-S nằm ngoài bộ 12."},{"step_no":6,"item_id":"BL-N3","kind":"sealed","answer":">= 2 loại từ nối nguyên nhân-kết quả, đúng chiều (because, so, as a result, that's why).","explanation_vi":"A-L3-CAUSE-S: c1 từ nối, c2 đúng chiều. A-L2-COMPENSATE-S: c1 diễn đạt vòng thành công, c2 <= 1 lần chuyển sang tiếng Việt cho từ nội dung."},{"step_no":6,"item_id":"step-6:note","kind":"note","answer":null,"explanation_vi":"T2 19/10 - N3 Vì sao (45-60 giây; Nói \"vì sao - nên\" cần nói >= 45 giây). Ghi activity_type = ACT-SPEAK-MONO (catalogue chỉ cho A-L3-CAUSE-S ở MONO). Xoay xở khi thiếu từ: chỉ chấm nếu có chỗ thiếu từ thật (vd. héo = wilt), cô xác nhận; không thì NULL. Cô không nói \"Why?\" trong lúc An nói."},{"step_no":7,"item_id":"step-7:note","kind":"note","answer":null,"explanation_vi":"T2 19/10 - N3 thử lại có câu mẫu. CHỈ khi N3 <= 2/4. Ghi dòng riêng: PRACTICE, attempt_no = 2, support_used = frame."},{"step_no":8,"item_id":"BL-N4","kind":"sealed","answer":"Quan điểm rõ; >= 2 lý do khác nhau; >= 1 ví dụ gắn với lý do. Không chấm đúng/sai quan điểm.","explanation_vi":"A-X1-TURN (c1 >= 60 giây, c2 <= 3 lần ngừng dài, c3 nói lại câu). Quan điểm, lý do, ví dụ: nhận xét chẩn đoán, không ghi dòng."},{"step_no":8,"item_id":"step-8:note","kind":"note","answer":null,"explanation_vi":"T2 19/10 - N4 (60-90 giây). Cô nghe trực tiếp => ACT-SPEAK-LIVE: chỉ ghi dòng cho A-X1-TURN (c1 >= 60 giây, c2 <= 3 lần ngừng > 3 giây, c3 nói lại câu thay vì bỏ dở). Nêu ý kiến (A-T7-OPINION) chỉ nhận xét trên phiếu, KHÔNG ghi dòng vì catalogue không nhận Nêu ý kiến ở ACT-SPEAK-LIVE."},{"step_no":9,"item_id":"step-9:note","kind":"note","answer":null,"explanation_vi":"T2 19/10 - N4 thử lại có gợi ý. CHỈ khi thiếu lý do/ví dụ, sau khi An nói xong. Ghi tutor_prompt, attempt_no = 2; chẩn đoán, không ghi dòng Nêu ý kiến (LIVE không nhận)."},{"step_no":10,"item_id":"step-10:note","kind":"note","answer":null,"explanation_vi":"T2 19/10 - N5 Trao đổi (4 phút). Chẩn đoán; A-L8-EXCHANGE-S ngoài bộ 12."},{"step_no":11,"item_id":"BL-V1","kind":"sealed","answer":">= 80% chỗ bắt buộc đúng quá khứ đơn; >= 3 động từ bất quy tắc khác nhau.","explanation_vi":"A-L1-PAST-W c1, c2."},{"step_no":11,"item_id":"step-11:note","kind":"note","answer":null,"explanation_vi":"T2 19/10 - V1 (8 phút). A-L1-PAST-W chỉ chấm khi bài >= 80 từ VÀ >= 6 chỗ bắt buộc dùng quá khứ; thiếu một trong hai => NULL (không phải 0)."},{"step_no":12,"item_id":"BL-V2","kind":"sealed","answer":"Chuỗi nhân quả >= 2 liên kết nối thành chuỗi.","explanation_vi":"A-L3-CAUSE-W (từ nối), A-L3-PARA-W (câu mở đoạn, >= 3 câu triển khai, câu kết, >= 4 từ nối), A-T4-CAUSE (nội dung đúng)."},{"step_no":12,"item_id":"step-12:note","kind":"note","answer":null,"explanation_vi":"T2 19/10 - V2 (12 phút). Viết đoạn văn chỉ chấm khi >= 80 từ, nếu không => NULL. Chuỗi gợi ý: lá xanh vì chlorophyll -> ngày ngắn, ít nắng -> cây ngừng làm chlorophyll mới, cái cũ phân hủy -> xanh mất -> vàng/cam vốn có lộ ra (một số cây tạo thêm đỏ)."},{"step_no":13,"item_id":"BL-G1","kind":"answer","answer":"went to the beach","explanation_vi":"CHẨN ĐOÁN cấu trúc: Quá khứ đơn. Câu hoàn thành/điền không phải cơ hội hợp lệ cho kỹ năng ngữ pháp (catalogue)."},{"step_no":13,"item_id":"BL-G2","kind":"answer","answer":"had a red bike","explanation_vi":"CHẨN ĐOÁN cấu trúc: Quá khứ đơn bất quy tắc. Câu hoàn thành/điền không phải cơ hội hợp lệ cho kỹ năng ngữ pháp (catalogue)."},{"step_no":13,"item_id":"BL-G3","kind":"answer","answer":"An elephant is bigger than a cat.","explanation_vi":"CHẨN ĐOÁN cấu trúc: So sánh hơn. Câu hoàn thành/điền không phải cơ hội hợp lệ cho kỹ năng ngữ pháp (catalogue)."},{"step_no":13,"item_id":"BL-G4","kind":"answer","answer":"The blue whale is the biggest animal.","explanation_vi":"CHẨN ĐOÁN cấu trúc: So sánh nhất. Câu hoàn thành/điền không phải cơ hội hợp lệ cho kỹ năng ngữ pháp (catalogue)."},{"step_no":13,"item_id":"BL-G5","kind":"answer","answer":"visit my grandparents","explanation_vi":"CHẨN ĐOÁN cấu trúc: going to. Câu hoàn thành/điền không phải cơ hội hợp lệ cho kỹ năng ngữ pháp (catalogue)."},{"step_no":13,"item_id":"BL-G6","kind":"answer","answer":"travel to Mars","explanation_vi":"CHẨN ĐOÁN cấu trúc: will dự đoán. Câu hoàn thành/điền không phải cơ hội hợp lệ cho kỹ năng ngữ pháp (catalogue)."},{"step_no":13,"item_id":"BL-G7","kind":"answer","answer":"seen snow","explanation_vi":"CHẨN ĐOÁN cấu trúc: Hiện tại hoàn thành (trải nghiệm). Câu hoàn thành/điền không phải cơ hội hợp lệ cho kỹ năng ngữ pháp (catalogue)."},{"step_no":13,"item_id":"BL-G8","kind":"answer","answer":"I took an umbrella because it was raining.","explanation_vi":"CHẨN ĐOÁN cấu trúc: Nối nguyên nhân. Câu hoàn thành/điền không phải cơ hội hợp lệ cho kỹ năng ngữ pháp (catalogue)."},{"step_no":13,"item_id":"BL-G9","kind":"answer","answer":"The ice was in the sun, so it melted.","explanation_vi":"CHẨN ĐOÁN cấu trúc: Nối kết quả. Câu hoàn thành/điền không phải cơ hội hợp lệ cho kỹ năng ngữ pháp (catalogue)."},{"step_no":13,"item_id":"BL-G10","kind":"answer","answer":"is made","explanation_vi":"CHẨN ĐOÁN cấu trúc: Bị động hiện tại (thử, mức B1). Câu hoàn thành/điền không phải cơ hội hợp lệ cho kỹ năng ngữ pháp (catalogue)."},{"step_no":13,"item_id":"step-13:note","kind":"note","answer":null,"explanation_vi":"T2 19/10 - Ngữ pháp (6 phút). Chỉ chẩn đoán _/10; không ghi dòng kỹ năng."}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W0-BASELINE' and it.version = 1 and it.published_at is not null)
on conflict (template_id, template_version, item_id) do nothing;

update english.inquiry_templates set status = 'published', published_at = now()
where id = 'A-W0-BASELINE' and version = 1 and published_at is null;

-- Inquiry template A-W1-VOLCANOES v1 (published after its sources and answer keys are in)
insert into english.sources(id, version, title, url, author, rights_note, modality, body, source_hash)
select r->>'id', (r->>'version')::int, r->>'title', r->>'url', r->>'author', r->>'rights_note', r->>'modality', r->>'body', r->>'source_hash'
from jsonb_array_elements($j$[{"id":"A-W1-VOLCANOES-S1","version":1,"title":"Why Do Volcanoes Erupt? (bài đọc VOL-R)","url":null,"author":"Tự soạn cho Pilot Kit A v0.2.1 (phụ huynh/Claude); không phải trích từ sách hay đề thi","rights_note":"Tự soạn (v0.2.1). Nguồn kiểm: NPS (https://www.nps.gov/subjects/volcanoes/volcanic-eruptions.htm), NASA Space Place (https://spaceplace.nasa.gov/volcanoes2/), USGS Kilauea (https://www.usgs.gov/volcanoes/kilauea), USGS 1980 Cataclysmic Eruption (https://www.usgs.gov/volcanoes/mount-st.-helens/science/1980-cataclysmic-eruption), USGS buồng magma phần lớn là đá nóng gần đặc (https://www.usgs.gov/faqs/how-big-magma-chamber-under-yellowstone). Đơn giản hóa có chủ ý: Kilauea \"usually\" phun chảy.","modality":"text","body":"Why Do Volcanoes Erupt?\n\nDeep under the ground, it is extremely hot. In some places, part of the rock melts. Melted rock under the ground is called magma.\n\nMagma is lighter than the solid rock around it, so it slowly rises. It often collects deep under a volcano, in a place called a magma chamber.\n\nMagma has gas in it, a bit like the gas in a bottle of fizzy drink. Deep underground, the heavy rock above presses on the magma, so the gas stays inside. But when the magma rises near the surface, there is less pressure. The gas comes out and makes bubbles. The bubbles grow bigger and push the magma up. When the push is strong enough, the magma breaks through the ground. This is an eruption. When magma comes out of a volcano, we call it lava.\n\nNot all eruptions are the same. Some magma is runny, like soup. The gas escapes easily, so the lava pours out and flows like a red river. Kilauea in Hawaii usually erupts this way. Other magma is thick and sticky, like honey. The gas is trapped, and the pressure builds up. As a result, the volcano explodes and throws ash high into the sky. Mount St. Helens in the USA had thick magma like this, and it exploded in 1980.","source_hash":"fae9c2c13ef29f90fa7c18be863925516c171f10a96d3a6646c3835aef37be8c"},{"id":"A-W1-VOLCANOES-S2","version":1,"title":"Dr Linh, volcano scientist (bài nghe VOL-L, file A_VOL_L)","url":null,"author":"Tự soạn cho Pilot Kit A v0.2.1 (phụ huynh/Claude); không phải trích từ sách hay đề thi; nhân vật Dr Linh là hư cấu","rights_note":"Tự soạn, TTS một giọng cố định 0,9x. Nguồn kiểm: USGS FAQ (https://www.usgs.gov/faqs/how-can-we-tell-when-volcano-will-erupt): dấu hiệu động đất, mặt đất phồng, thay đổi khí; USGS Eruption forecast (https://www.usgs.gov/natural-hazards/volcano-hazards/eruption-forecast): dự báo là xác suất, không phải một ngày chính xác.","modality":"audio","body":null,"source_hash":"fadd1773936d3a2ba3dd4aaf8e5abbe8753200d0e3d303ecfbaef4feb12f352f"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W1-VOLCANOES' and it.version = 1 and it.published_at is not null)
on conflict (id, version) do nothing;

insert into english.source_transcripts(source_id, source_version, transcript)
select r->>'id', (r->>'version')::int, r->>'transcript'
from jsonb_array_elements($j$[{"id":"A-W1-VOLCANOES-S2","version":1,"transcript":"Hi, I'm Dr Linh, and I am a volcano scientist. People often ask me, \"Can you tell the exact day a volcano will erupt?\" The honest answer is no. But we can see warning signs.\n\nEvery day, my team watches a volcano for three signs. First, we count small earthquakes. When magma moves up under the ground, it breaks rock, and this makes many small earthquakes. Second, we measure the ground. When magma collects under a volcano, the ground can rise a little, like a balloon. Third, we check the gas. When magma moves closer to the surface, the gas coming out of the volcano can change.\n\nIf we see all three signs getting stronger, we tell the people who live nearby. Then they can leave their homes in time. Our job is not to stop eruptions. Our job is to keep people safe."}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W1-VOLCANOES' and it.version = 1 and it.published_at is not null)
on conflict (source_id, source_version) do nothing;

update english.sources set published_at = now()
where version = 1 and id in ('A-W1-VOLCANOES-S1', 'A-W1-VOLCANOES-S2') and published_at is null;

insert into english.inquiry_templates(id, version, track_id, title_vi, big_question_en, big_question_vi, week, date_from, date_to, domain_bucket, target_ids, steps, sources, catalogue_version, status, source_hash)
select r->>'id', (r->>'version')::int, r->>'track_id', r->>'title_vi', r->>'big_question_en', r->>'big_question_vi', (r->>'week')::int,
  (r->>'date_from')::date, (r->>'date_to')::date, r->>'domain_bucket',
  array(select e from jsonb_array_elements_text(r->'target_ids') with ordinality as t(e, n) order by n), r->'steps', r->'sources', '0.2.1-draft', 'draft', '04bfdbb0957501ad68430ef0021b616b5a673699d3431c3916c65ea7d9020a93'
from jsonb_array_elements($j$[{"id":"A-W1-VOLCANOES","version":1,"track_id":"A","title_vi":"Tuần 1 - Núi lửa","big_question_en":"Why do volcanoes erupt?","big_question_vi":"Vì sao núi lửa phun trào?","week":1,"date_from":"2026-10-19","date_to":"2026-10-25","domain_bucket":"science","target_ids":["A-T1-TEXT-L","A-T1-TEXT-R","A-L3-CAUSE-S","A-L3-CAUSE-W","A-L3-PARA-W","A-L4-PROCESS-S","A-L2-CHUNKS","A-L2-COMPENSATE-S","A-T4-CAUSE","A-T7-OPINION","A-X1-TURN"],"steps":[{"step_no":1,"activity_type":"ACT-SPEAK-LIVE","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"What do you know about volcanoes? (You can speak Vietnamese.) Tip for a missing word: It's a kind of... / It's like... / It's a thing that... / I don't know the word, but... / How do you say ... in English?","time_min":25,"planned_date":"2026-10-19","items":[],"self_check_vi":[]},{"step_no":2,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["A-T1-TEXT-L"],"prompt_en":"Listen (maximum 2 times, no text). Answer the questions.","time_min":10,"planned_date":"2026-10-20","items":[{"id":"W1-L1","kind":"mcq","stem":"What is the talk mainly about?","options":["a) how volcanoes are made","b) how scientists watch for warning signs of an eruption","c) why Dr Linh likes volcanoes","d) how to stop an eruption"],"target_id":"A-T1-TEXT-L"},{"id":"W1-L2","kind":"short","stem":"How many warning signs does Dr Linh's team watch?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W1-L3","kind":"short","stem":"What makes many small earthquakes?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W1-L4","kind":"short","stem":"What can happen to the ground when magma collects under a volcano?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W1-L5","kind":"short","stem":"What does the team do if all three signs get stronger?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W1-L6","kind":"open","stem":"Dr Linh says, \"Our job is not to stop eruptions.\" Why do you think she says this?","options":[],"target_id":"A-T2-INFER-L"}],"self_check_vi":[]},{"step_no":3,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["A-T1-TEXT-R"],"prompt_en":"Read the text once, then answer. You may look back at the text.","time_min":18,"planned_date":"2026-10-20","items":[{"id":"W1-R1","kind":"mcq","stem":"What is the text mainly about?","options":["a) why the inside of the Earth is hot","b) why volcanoes erupt, and why eruptions are different","c) the story of Mount St. Helens","d) how to make lava at home"],"target_id":"A-T1-TEXT-R"},{"id":"W1-R2","kind":"short","stem":"What is magma?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W1-R3","kind":"short","stem":"Why does magma start to rise from deep under the ground?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W1-R4","kind":"short","stem":"Deep underground, why does the gas stay inside the magma?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W1-R5","kind":"short","stem":"Put in order: (A) The bubbles push the magma up. (B) Magma rises near the surface. (C) The magma breaks through the ground. (D) The gas comes out and makes bubbles.","options":["A","B","C","D"],"target_id":"A-T1-TEXT-R"},{"id":"W1-R6","kind":"short","stem":"Why can a volcano with thick, sticky magma explode?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W1-R7","kind":"open","stem":"Scientists find that the magma under a volcano is very runny. Will the next eruption probably be a big explosion? Why or why not? Give a clue from the text.","options":[],"target_id":"A-T2-INFER-R"},{"id":"W1-R8","kind":"short","stem":"\"The gas is trapped.\" What does 'trapped' mean?","options":[],"target_id":"A-T2-INFER-R"}],"self_check_vi":[]},{"step_no":4,"activity_type":"ACT-CANVAS-BASIC","mode":"PRACTICE","purpose":[],"target_ids":["A-T4-CAUSE"],"prompt_en":"Main idea: Volcanoes erupt because... Why (3 cards, each one is the result of the one before): [Magma is lighter than rock, so...] -> [Near the surface,...] -> [The bubbles...]. Example: choose Kilauea or Mount St. Helens. How did it erupt? Why?","time_min":18,"planned_date":"2026-10-21","items":[{"id":"W1-CV","kind":"open","stem":"Fill in the three cards and the example.","options":[],"target_id":"A-T4-CAUSE"}],"self_check_vi":[]},{"step_no":5,"activity_type":"ACT-SPEAK-MONO","mode":"PRACTICE","purpose":[],"target_ids":["A-L3-CAUSE-S","A-L2-CHUNKS"],"prompt_en":"Why does magma rise, and what happens to the gas in it? - Magma is... / Magma rises because... / Deep underground, the gas stays inside because... / When the magma comes near the surface,..., so... / As a result,... (Think for 1 minute, then speak 45-60 seconds.)","time_min":12,"planned_date":"2026-10-21","items":[],"self_check_vi":[]},{"step_no":6,"activity_type":"ACT-WRITE","mode":"PRACTICE","purpose":[],"target_ids":["A-L3-CAUSE-W","A-L2-CHUNKS"],"prompt_en":"Magma and lava: what is the difference? Why does magma come up to the surface? Magma is..., but lava is... / Magma is lighter than..., so... / When it comes near the surface, the gas... / That is why... (50-70 words)","time_min":18,"planned_date":"2026-10-22","items":[],"self_check_vi":[]},{"step_no":7,"activity_type":"ACT-SELF-REVIEW","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Check your own writing.","time_min":7,"planned_date":"2026-10-22","items":[],"self_check_vi":["Câu đầu của bạn đã trả lời câu hỏi chưa?","Bạn đã nói vì sao magma đi lên và vì sao khí đẩy nó chưa?","Bạn đã dùng 2 từ nối khác nhau và 4 từ mới chưa?"]},{"step_no":8,"activity_type":"ACT-SPEAK-MONO","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-L3-CAUSE-S","A-L4-PROCESS-S","A-T4-CAUSE","A-L2-CHUNKS"],"prompt_en":"How and why does a volcano erupt? Explain it step by step, from deep under the ground to the eruption. (30 seconds to think, no writing. Speak 60-90 seconds.)","time_min":7,"planned_date":"2026-10-23","items":[{"id":"W1-SIC","kind":"open","stem":"How and why does a volcano erupt? Explain step by step.","options":[],"target_id":"A-L3-CAUSE-S"}],"self_check_vi":[]},{"step_no":9,"activity_type":"ACT-SPEAK-LIVE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-X1-TURN","A-L2-COMPENSATE-S"],"prompt_en":"Choose one picture. It must be something you know how to use, but you do not know its English name. Tell me about it: what it looks like, what we use it for, and how you use it. (30 seconds to think, no writing. Speak 60-90 seconds.)","time_min":4,"planned_date":"2026-10-23","items":[{"id":"W1-LIVE","kind":"open","stem":"Choose one picture and tell me about it.","options":[],"target_id":"A-X1-TURN"}],"self_check_vi":[]},{"step_no":10,"activity_type":"ACT-SPEAK-MONO","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-T7-OPINION"],"prompt_en":"Would you like to live near a volcano? Why or why not? Give your reasons and an example. Talk for at least one minute. (Then: Now you can ask me two questions about volcanoes.)","time_min":3,"planned_date":"2026-10-23","items":[{"id":"W1-OP","kind":"open","stem":"Would you like to live near a volcano? Why or why not? Give your reasons and an example. Talk for at least one minute.","options":[],"target_id":"A-T7-OPINION"}],"self_check_vi":[]},{"step_no":11,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-L3-CAUSE-W","A-L3-PARA-W","A-T4-CAUSE","A-L2-CHUNKS"],"prompt_en":"Some volcanoes explode, but others let lava flow out gently. Why? Write one paragraph (80-120 words). (20 minutes. No dictionary, no text.)","time_min":20,"planned_date":"2026-10-23","items":[{"id":"W1-WIC","kind":"open","stem":"Some volcanoes explode, but others let lava flow out gently. Why?","options":[],"target_id":"A-L3-CAUSE-W"}],"self_check_vi":[]},{"step_no":12,"activity_type":"ACT-SELF-REVIEW","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-A1-SELFASSESS"],"prompt_en":"Before you hear any feedback, check your own paragraph.","time_min":3,"planned_date":"2026-10-23","items":[],"self_check_vi":["Câu đầu của bạn đã trả lời câu hỏi (vì sao có núi lửa nổ, có núi lửa chảy nhẹ) chưa?","Bạn đã nói vì sao magma loãng thì dung nham chảy ra, magma đặc thì núi lửa nổ chưa?","Bạn đã dùng 2 từ nối khác nhau và 4 từ mới chưa?","Một điều mình làm tốt: ______","Một điều mình muốn sửa: ______"]},{"step_no":13,"activity_type":"ACT-REVISE","mode":"REVISION","purpose":[],"target_ids":["A-A3-REDRAFT"],"prompt_en":"Read each hint. Find the place in your paragraph and fix it. Underline what you changed. Write one line for each hint: 'Mình đã đổi ... thành ... vì ...'.","time_min":15,"planned_date":"2026-10-23","items":[],"self_check_vi":[]}],"sources":[{"id":"A-W1-VOLCANOES-S1","version":1,"title":"Why Do Volcanoes Erupt? (bài đọc VOL-R)","modality":"text","url":null},{"id":"A-W1-VOLCANOES-S2","version":1,"title":"Dr Linh, volcano scientist (bài nghe VOL-L, file A_VOL_L)","modality":"audio","url":null}]}]$j$::jsonb) as r
on conflict (id, version) do nothing;

insert into english.template_item_keys(template_id, template_version, item_id, step_no, kind, answer, explanation_vi)
select 'A-W1-VOLCANOES', 1, r->>'item_id', (r->>'step_no')::int, r->>'kind', r->>'answer', r->>'explanation_vi'
from jsonb_array_elements($j$[{"step_no":1,"item_id":"step-1:note","kind":"note","answer":null,"explanation_vi":"T2 19/10 (25') - Câu hỏi lớn + đoán trước + mẹo nói tiếp khi quên từ (luyện với 2 vật khác bộ ảnh T6, vd. cái dập ghim, cái bấm lỗ). CHƯA phát thẻ 8 cụm từ (nghĩa và câu ví dụ trùng đáp án bài đọc/nghe)."},{"step_no":2,"item_id":"W1-L1","kind":"answer","answer":"b","explanation_vi":"Ý chính (c1)."},{"step_no":2,"item_id":"W1-L2","kind":"sealed","answer":"Three.","explanation_vi":"Chi tiết 1/4."},{"step_no":2,"item_id":"W1-L3","kind":"sealed","answer":"Magma moving up and breaking rock.","explanation_vi":"Chi tiết 2/4."},{"step_no":2,"item_id":"W1-L4","kind":"sealed","answer":"It can rise a little (like a balloon).","explanation_vi":"Chi tiết 3/4."},{"step_no":2,"item_id":"W1-L5","kind":"sealed","answer":"They tell / warn the people who live nearby (so they can leave).","explanation_vi":"Chi tiết 4/4. Cần >= 3/4."},{"step_no":2,"item_id":"W1-L6","kind":"sealed","answer":"Vì con người không ngăn được núi lửa phun; việc của nhà khoa học là cảnh báo để người dân an toàn. Dấu hiệu: 'Our job is to keep people safe'.","explanation_vi":"CHẨN ĐOÁN (mục đích người nói). Được trả lời tiếng Việt, ghi lang=vi."},{"step_no":2,"item_id":"step-2:note","kind":"note","answer":null,"explanation_vi":"T3 20/10 (10') - Bài nghe ở nhà, bố/mẹ ngồi cạnh. Nghe hiểu: c1 ý chính, c2 >= 3/4 chi tiết. L6 chẩn đoán."},{"step_no":3,"item_id":"W1-R1","kind":"answer","answer":"b","explanation_vi":"Ý chính (c1)."},{"step_no":3,"item_id":"W1-R2","kind":"sealed","answer":"Melted rock under the ground.","explanation_vi":"Chi tiết 1/5."},{"step_no":3,"item_id":"W1-R3","kind":"sealed","answer":"It is lighter than the solid rock around it.","explanation_vi":"Chi tiết 2/5. Chữ \"start\" khóa đúng giai đoạn đầu (nhẹ hơn đá), không phải giai đoạn bong bóng đẩy."},{"step_no":3,"item_id":"W1-R4","kind":"sealed","answer":"The heavy rock above presses on it (high pressure).","explanation_vi":"Chi tiết 3/5 (nhân quả)."},{"step_no":3,"item_id":"W1-R5","kind":"sealed","answer":"B, D, A, C","explanation_vi":"Chi tiết 4/5 (trình tự)."},{"step_no":3,"item_id":"W1-R6","kind":"sealed","answer":"The gas is trapped, so the pressure builds up (it cannot get out).","explanation_vi":"Chi tiết 5/5 (nhân quả có trong bài). Cần >= 4/5 chi tiết."},{"step_no":3,"item_id":"W1-R7","kind":"sealed","answer":"Probably not. Gas escapes easily from runny magma, so the lava pours out and flows.","explanation_vi":"CHẨN ĐOÁN (suy luận)."},{"step_no":3,"item_id":"W1-R8","kind":"sealed","answer":"Cannot get out (bị giữ lại, mắc kẹt).","explanation_vi":"CHẨN ĐOÁN (nghĩa từ)."},{"step_no":3,"item_id":"step-3:note","kind":"note","answer":null,"explanation_vi":"T3 20/10 (18') - Bài đọc ở nhà. Xem lại bài = bình thường (không ghi source_open). Đọc hiểu: c1 ý chính, c2 >= 4/5 chi tiết (R2-R6)."},{"step_no":4,"item_id":"W1-CV","kind":"sealed","answer":"Magma nhẹ hơn đá -> nổi lên, gom trong buồng magma -> gần mặt đất áp suất giảm -> khí thoát ra thành bong bóng -> bong bóng lớn dần, đẩy magma -> magma xuyên qua mặt đất = phun trào. Magma loãng: khí thoát dễ -> dung nham chảy. Magma đặc: khí bị giữ -> áp suất tăng -> nổ.","explanation_vi":"Luyện tập, tùy chọn ghi 1 dòng Giải thích chuỗi nguyên nhân."},{"step_no":4,"item_id":"step-4:note","kind":"note","answer":null,"explanation_vi":"T4 21/10 (6' + 12') - Làm đầu tiên: phát 8 cụm từ + thẻ từ (6'), SAU khi An nộp bài nghe và bài đọc. Rồi Canvas (12'): được xem lại bài đọc (source_open), viết thẻ tiếng Việt nếu bí. 8 cụm từ: magma = đá nóng chảy dưới lòng đất · lava = dung nham · melted rock = đá nóng chảy · rise/rises = đi lên · gas bubbles = bong bóng khí · pressure builds up = áp suất tăng dần · erupt/an eruption = phun trào · as a result = kết quả là. Đáp án gợi ý cho bố mẹ: Magma nhẹ hơn đá -> nổi lên, gom trong buồng magma -> gần mặt đất áp suất giảm -> khí thoát ra thành bong bóng -> bong bóng lớn dần, đẩy magma -> magma xuyên qua mặt đất = phun trào. Magma loãng: khí thoát dễ -> dung nham chảy. Magma đặc: khí bị giữ -> áp suất tăng -> nổ."},{"step_no":5,"item_id":"step-5:note","kind":"note","answer":null,"explanation_vi":"T4 21/10 (12') - Luyện nói có câu mẫu, ghi âm trên máy (chế độ máy bay). support_used = frame. Bố mẹ nghe 1 lần, đánh dấu từ nối và từ mới, không cần gõ chữ."},{"step_no":6,"item_id":"step-6:note","kind":"note","answer":null,"explanation_vi":"T5 22/10 (18') - Luyện viết có câu mẫu. Chỉ ghi A-L2-CHUNKS nếu >= 60 từ; không ghi Viết đoạn văn (< 80 từ)."},{"step_no":7,"item_id":"step-7:note","kind":"note","answer":null,"explanation_vi":"T5 22/10 (5' + 2' thẻ từ) - Tự kiểm sau khi viết luyện."},{"step_no":8,"item_id":"W1-SIC","kind":"sealed","answer":"Magma nhẹ hơn đá -> nổi lên, gom trong buồng magma -> gần mặt đất áp suất giảm -> khí thoát ra thành bong bóng -> bong bóng lớn dần, đẩy magma -> magma xuyên qua mặt đất = phun trào. Magma loãng: khí thoát dễ -> dung nham chảy. Magma đặc: khí bị giữ -> áp suất tăng -> nổ.","explanation_vi":"A-L3-CAUSE-S (>= 2 loại từ nối, đúng chiều); A-L4-PROCESS-S (nêu tên quá trình + kết quả, >= 3 bước đúng thứ tự); A-T4-CAUSE (>= 2 liên kết đúng, nối thành chuỗi); A-L2-CHUNKS (>= 4 trong 8 cụm từ)."},{"step_no":8,"item_id":"step-8:note","kind":"note","answer":null,"explanation_vi":"T6 23/10 (7') - Nói tự làm (SIC), bài kiểm tra trong buổi, cô quan sát trực tiếp, ghi âm. Ghi activity_type = ACT-SPEAK-MONO. Không câu mẫu, không vở. Nói trôi chảy và Xoay xở khi thiếu từ được chấm ở lượt LIVE kế tiếp, không ở đây."},{"step_no":9,"item_id":"W1-LIVE","kind":"sealed","answer":"Không có đáp án mẫu. Cô ghi: vật An chọn, từ An chưa biết, cách An diễn đạt vòng (a thing that..., it is like...), có chuyển sang tiếng Việt không.","explanation_vi":"A-X1-TURN (c1 >= 60 giây; c2 <= 3 lần ngừng dài; c3 nói lại câu) và A-L2-COMPENSATE-S (c1 >= 1 lần diễn đạt vòng thành công bằng tiếng Anh; c2 <= 1 lần chuyển sang tiếng Việt), hoặc NULL."},{"step_no":9,"item_id":"step-9:note","kind":"note","answer":null,"explanation_vi":"T6 23/10 (4') - Lượt nói trực tiếp (kit mục 3.0, \"Thử thách thiếu từ\"). Cô đưa 3 ảnh: tweezers (cái nhíp) · funnel (cái phễu) · magnifying glass (kính lúp). Cô không nói tên tiếng Anh trước T6; cô chỉ nói \"Bắt đầu nhé\" / \"Còn 30 giây\", không nhắc \"giải thích cách khác\". Ghi activity_type = ACT-SPEAK-LIVE, context_topic = lab-tools, chỉ cô chấm; cô bấm giờ (duration_s; c1 Nói trôi chảy cần >= 60 giây). Nói trôi chảy: c1 >= 60 giây, c2 <= 3 lần ngừng > 3 giây, c3 nói lại câu thay vì bỏ dở. Xoay xở khi thiếu từ: cô xác nhận có chỗ thiếu từ thật; An biết tên cả 3 vật (đổi bộ ảnh) hoặc không có chỗ thiếu thật => NULL, đó là kết quả hợp lệ."},{"step_no":10,"item_id":"W1-OP","kind":"sealed","answer":"Không có đáp án đúng/sai; chấm lập luận.","explanation_vi":"A-T7-OPINION: c1 quan điểm rõ; c2 >= 2 lý do khác nhau, liên quan; c3 >= 1 ví dụ gắn với một lý do."},{"step_no":10,"item_id":"step-10:note","kind":"note","answer":null,"explanation_vi":"T6 23/10 (3') - Nói ý kiến (OP), ghi âm trên máy. Cô hỏi một lần, nghĩ 30 giây, không hỏi thêm \"Why?\" khi An đang nói; An nói ít nhất 1 phút. Chấm: c1 quan điểm rõ, c2 >= 2 lý do khác nhau, c3 >= 1 ví dụ gắn với lý do. Không chấm quan điểm đúng/sai. Ghi activity_type = ACT-SPEAK-MONO (catalogue không nhận Nêu ý kiến ở ACT-SPEAK-LIVE). Sau đó: \"Now you can ask me two questions about volcanoes.\" (luyện hỏi, chỉ ghi chú, không ghi dòng)."},{"step_no":11,"item_id":"W1-WIC","kind":"sealed","answer":"Magma loãng -> khí thoát dễ -> dung nham chảy nhẹ; magma đặc -> khí bị giữ -> áp suất tăng -> nổ.","explanation_vi":"A-L3-CAUSE-W c1-c2; A-L3-PARA-W c1-c3; A-T4-CAUSE c1-c2; A-L2-CHUNKS c1-c2."},{"step_no":11,"item_id":"step-11:note","kind":"note","answer":null,"explanation_vi":"T6 23/10 (20') - Viết tự làm, bài kiểm tra trong buổi, cô có mặt, không can thiệp. Dùng thì quá khứ: không ghi (đề giải thích). Viết đoạn văn chỉ chấm khi >= 80 từ."},{"step_no":12,"item_id":"step-12:note","kind":"note","answer":null,"explanation_vi":"T6 23/10 (3') - Tự kiểm TRƯỚC khi nghe góp ý. A-A1-SELFASSESS thuộc nhóm theo dõi, không vào mẫu số 12."},{"step_no":13,"item_id":"step-13:note","kind":"note","answer":null,"explanation_vi":"T6 23/10 (cô chọn <= 3 gợi ý 7' + An sửa 15') - Gợi ý chỉ chỗ và loại lỗi, không đưa câu đúng. Luôn is_first_attempt = N, chung learning_family với bản gốc. Thêm: nếu cô hỏi về chiều nhân quả, đọc to câu đó và hỏi 'cái gì xảy ra trước?'."}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W1-VOLCANOES' and it.version = 1 and it.published_at is not null)
on conflict (template_id, template_version, item_id) do nothing;

update english.inquiry_templates set status = 'published', published_at = now()
where id = 'A-W1-VOLCANOES' and version = 1 and published_at is null;

