insert into english.sources(id, version, title, url, author, rights_note, modality, body, source_hash)
select r->>'id', (r->>'version')::int, r->>'title', r->>'url', r->>'author', r->>'rights_note', r->>'modality', r->>'body', r->>'source_hash'
from jsonb_array_elements($j$[{"id":"A-W2-WATERCYCLE-S1","version":1,"title":"The Never-Ending Journey of Water (bài đọc WAT-R)","url":null,"author":"Tự soạn cho Pilot Kit A v0.2.1 (phụ huynh/Claude); không phải trích từ sách hay đề thi","rights_note":"Tự soạn, không sao chép. Nguồn kiểm: NASA GPM (https://gpm.nasa.gov/resources/faq/how-does-water-cycle-work), NASA Science for Kids (https://science.nasa.gov/kids/earth/what-is-the-water-cycle/), USGS Water Science School (https://www.usgs.gov/water-science-school/science/condensation-and-water-cycle).","modality":"text","body":"The Never-Ending Journey of Water\n\nSome of the water in your glass may once have been in a cloud, a river or the sea. Water moves around the Earth again and again. This journey is called the water cycle.\n\nThe journey starts with the Sun. The Sun heats the water in seas, rivers and lakes. Some of the water turns into a gas called water vapour. We cannot see water vapour, but it is in the air all around us. This change from liquid water to gas is called evaporation. Plants help too: they let out water vapour from their leaves.\n\nWarm air with water vapour rises. High in the sky, the air is cold, so the water vapour cools down. It changes back into tiny drops of water. This is called condensation. Millions of these tiny drops make a cloud.\n\nInside the cloud, the drops bump into each other and join together. They grow bigger and heavier. When they are too heavy to stay in the air, they fall as rain. Sometimes they fall as snow or hail instead. This is called precipitation.\n\nThe rain flows into rivers and back to the sea, or it soaks into the ground. Then the Sun heats the water again, and the journey starts again.","source_hash":"5ff24a37e4a6636cde66956becda72b3e4e4991d514cb505acc6465a75e6ff05"},{"id":"A-W2-WATERCYCLE-S2","version":1,"title":"Mai and the cold glass (bài nghe WAT-L, file A_WAT_L)","url":null,"author":"Tự soạn cho Pilot Kit A v0.2.1 (phụ huynh/Claude); không phải trích từ sách hay đề thi; nhân vật Mai là hư cấu","rights_note":"Tự soạn, TTS một giọng cố định 0,9x. Nguồn kiểm: USGS Water Science School (nước ngoài cốc lạnh ngày ẩm là ngưng tụ).","modality":"audio","body":null,"source_hash":"c45866aa18a4d9ac80dfc22c84a87911ead1978ebfd19dfe57ee458dfd81b564"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W2-WATERCYCLE' and it.version = 1 and it.published_at is not null)
on conflict (id, version) do nothing;

insert into english.source_transcripts(source_id, source_version, transcript)
select r->>'id', (r->>'version')::int, r->>'transcript'
from jsonb_array_elements($j$[{"id":"A-W2-WATERCYCLE-S2","version":1,"transcript":"Hi, I'm Mai. Yesterday was a very hot day, and the air felt wet, so I made a glass of iced water. After ten minutes, I saw something strange. There were lots of small drops of water on the outside of the glass! The table under the glass was wet too.\n\nAt first, I thought the glass had a hole. But the water inside did not go down. So where did the drops come from?\n\nMy teacher explained it to me. The air around us has water vapour in it. When the warm air touched the cold glass, the water vapour cooled down. It changed into tiny drops of liquid water on the glass. This is called condensation.\n\nThe same thing happens in the sky. High up, the air is cold, so water vapour cools and makes tiny drops. That is how clouds start. My cold glass showed me the beginning of a cloud!"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W2-WATERCYCLE' and it.version = 1 and it.published_at is not null)
on conflict (source_id, source_version) do nothing;

update english.sources set published_at = now()
where version = 1 and id in ('A-W2-WATERCYCLE-S1', 'A-W2-WATERCYCLE-S2') and published_at is null;

insert into english.inquiry_templates(id, version, track_id, title_vi, big_question_en, big_question_vi, week, date_from, date_to, domain_bucket, target_ids, steps, sources, catalogue_version, status, source_hash)
select r->>'id', (r->>'version')::int, r->>'track_id', r->>'title_vi', r->>'big_question_en', r->>'big_question_vi', (r->>'week')::int,
  (r->>'date_from')::date, (r->>'date_to')::date, r->>'domain_bucket',
  array(select e from jsonb_array_elements_text(r->'target_ids') with ordinality as t(e, n) order by n), r->'steps', r->'sources', '0.2.1-draft', 'draft', '0e5ee89d1bba142bca0c4b2df7ca20c950df3cbe822cc0395c9be0b00a459e48'
from jsonb_array_elements($j$[{"id":"A-W2-WATERCYCLE","version":1,"track_id":"A","title_vi":"Tuần 2 - Vòng tuần hoàn của nước","big_question_en":"Where does rain come from?","big_question_vi":"Mưa từ đâu đến?","week":2,"date_from":"2026-10-26","date_to":"2026-11-01","domain_bucket":"science","target_ids":["A-T1-TEXT-L","A-T1-TEXT-R","A-L3-CAUSE-S","A-L3-CAUSE-W","A-L3-PARA-W","A-L4-PROCESS-S","A-L1-PAST-W","A-L2-CHUNKS","A-L2-COMPENSATE-S","A-T4-CAUSE","A-T7-OPINION","A-X1-TURN"],"steps":[{"step_no":1,"activity_type":"ACT-SPEAK-LIVE","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Where does rain come from? (You can speak Vietnamese.) Tip for a missing word: It's a kind of... / It's like... / It's a thing that...","time_min":10,"planned_date":"2026-10-26","items":[],"self_check_vi":[]},{"step_no":2,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-T1-TEXT-L"],"prompt_en":"Listen (maximum 2 times, no text). Answer the questions.","time_min":13,"planned_date":"2026-10-26","items":[{"id":"W2-L1","kind":"mcq","stem":"What is the talk mainly about?","options":["a) how to make iced water","b) why drops of water appeared on the outside of a cold glass","c) why Mai's glass had a hole","d) how rain falls"],"target_id":"A-T1-TEXT-L"},{"id":"W2-L2","kind":"short","stem":"What was the weather like?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W2-L3","kind":"short","stem":"What did Mai think at first?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W2-L4","kind":"short","stem":"What is in the air around us?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W2-L5","kind":"short","stem":"What happened to the water vapour when it touched the cold glass?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W2-L6","kind":"open","stem":"How did Mai know that the glass did NOT have a hole?","options":[],"target_id":"A-T2-INFER-L"}],"self_check_vi":[]},{"step_no":3,"activity_type":"ACT-SPEAK-LIVE","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Say the words after the tutor. Listen for the ending sounds -s and -ed in verbs you already know (not this week's topic). Tomorrow's experiment: a glass with ice and a glass without ice.","time_min":22,"planned_date":"2026-10-26","items":[],"self_check_vi":[]},{"step_no":4,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["A-T1-TEXT-R"],"prompt_en":"Read the text once, then answer. You may look back at the text.","time_min":28,"planned_date":"2026-10-27","items":[{"id":"W2-R1","kind":"mcq","stem":"What is the text mainly about?","options":["a) why we should drink water","b) how water moves around the Earth again and again","c) how plants drink water","d) why the sea is salty"],"target_id":"A-T1-TEXT-R"},{"id":"W2-R2","kind":"short","stem":"What heats the water in seas, rivers and lakes?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W2-R3","kind":"short","stem":"What is evaporation?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W2-R4","kind":"short","stem":"Why does water vapour cool down high in the sky?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W2-R5","kind":"short","stem":"Put in order: (A) the drops join and grow heavy (B) water vapour rises (C) the Sun heats the water (D) rain falls (E) tiny drops make a cloud","options":["A","B","C","D","E"],"target_id":"A-T1-TEXT-R"},{"id":"W2-R6","kind":"short","stem":"Why do the drops fall from the cloud?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W2-R7","kind":"open","stem":"On a cold winter morning, you can see your breath like a little white cloud. Use the text to explain why.","options":[],"target_id":"A-T2-INFER-R"},{"id":"W2-R8","kind":"short","stem":"\"...it soaks into the ground.\" What does 'soaks into' mean?","options":[],"target_id":"A-T2-INFER-R"}],"self_check_vi":[]},{"step_no":5,"activity_type":"ACT-CANVAS-BASIC","mode":"PRACTICE","purpose":[],"target_ids":["A-T4-CAUSE"],"prompt_en":"Main idea: Water moves in a cycle: ... Why (4 cards): [The Sun heats the water, so...] -> [Water vapour rises and...] -> [Tiny drops...] -> [The drops get heavy, so...]. Example: your glass of iced water on Tuesday - which step is it?","time_min":18,"planned_date":"2026-10-28","items":[{"id":"W2-CV","kind":"open","stem":"Fill in the 4 cards and the example.","options":[],"target_id":"A-T4-CAUSE"}],"self_check_vi":[]},{"step_no":6,"activity_type":"ACT-SPEAK-MONO","mode":"PRACTICE","purpose":[],"target_ids":["A-L3-CAUSE-S","A-L2-CHUNKS"],"prompt_en":"After the rain, there is a puddle on the road. On a sunny day, it disappears. Why? - After the rain,... / The Sun... / The water turns into... This is called... / We cannot see..., so... / That's why... (45-60 seconds)","time_min":12,"planned_date":"2026-10-28","items":[],"self_check_vi":[]},{"step_no":7,"activity_type":"ACT-WRITE","mode":"PRACTICE","purpose":[],"target_ids":["A-L3-CAUSE-W","A-L2-CHUNKS"],"prompt_en":"How does a cloud form? - First, the Sun... / The water vapour rises, and high in the sky... / Because the air is cold,... / Millions of tiny drops... (50-70 words)","time_min":18,"planned_date":"2026-10-29","items":[],"self_check_vi":[]},{"step_no":8,"activity_type":"ACT-SELF-REVIEW","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Check your own writing.","time_min":7,"planned_date":"2026-10-29","items":[],"self_check_vi":["Câu đầu của bạn đã trả lời câu hỏi chưa?","Bạn đã nói đủ: mặt trời làm nóng -> hơi nước bay lên -> lạnh nên thành giọt -> mây chưa?","Bạn đã dùng 2 từ nối khác nhau và 4 từ mới chưa?"]},{"step_no":9,"activity_type":"ACT-SPEAK-MONO","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-L3-CAUSE-S","A-L4-PROCESS-S","A-T4-CAUSE","A-L2-CHUNKS"],"prompt_en":"How does the water cycle work? Tell the journey of a drop of water from the sea, up to a cloud, and back to the sea. (30 seconds to think. Speak 60-90 seconds.)","time_min":7,"planned_date":"2026-10-30","items":[{"id":"W2-SIC","kind":"open","stem":"Tell the journey of a drop of water from the sea, up to a cloud, and back to the sea.","options":[],"target_id":"A-L3-CAUSE-S"}],"self_check_vi":[]},{"step_no":10,"activity_type":"ACT-SPEAK-LIVE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-X1-TURN","A-L2-COMPENSATE-S"],"prompt_en":"Choose one picture. It must be something you know how to use, but you do not know its English name. Tell me about it: what it looks like, what we use it for, and how you use it. (30 seconds to think, no writing. Speak 60-90 seconds.)","time_min":4,"planned_date":"2026-10-30","items":[{"id":"W2-LIVE","kind":"open","stem":"Choose one picture and tell me about it.","options":[],"target_id":"A-X1-TURN"}],"self_check_vi":[]},{"step_no":11,"activity_type":"ACT-SPEAK-MONO","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-T7-OPINION"],"prompt_en":"Do you like rainy days or sunny days more? Why? Give your reasons and an example. Talk for at least one minute. (Then: Now ask me two questions about rain or clouds.)","time_min":3,"planned_date":"2026-10-30","items":[{"id":"W2-OP","kind":"open","stem":"Do you like rainy days or sunny days more? Why? Give your reasons and an example. Talk for at least one minute.","options":[],"target_id":"A-T7-OPINION"}],"self_check_vi":[]},{"step_no":12,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-L1-PAST-W","A-L3-CAUSE-W","A-L3-PARA-W","A-T4-CAUSE","A-L2-CHUNKS"],"prompt_en":"Write a report of your cold-glass experiment in one paragraph (80-120 words). What did you do? What did you see? Why did it happen? (20 minutes. No dictionary, no notes.)","time_min":20,"planned_date":"2026-10-30","items":[{"id":"W2-WIC","kind":"open","stem":"Write a report of your cold-glass experiment.","options":[],"target_id":"A-L1-PAST-W"}],"self_check_vi":[]},{"step_no":13,"activity_type":"ACT-SELF-REVIEW","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-A1-SELFASSESS"],"prompt_en":"Before you hear any feedback, check your own report.","time_min":3,"planned_date":"2026-10-30","items":[],"self_check_vi":["Bạn đã kể đủ: bạn đã làm gì, bạn đã thấy gì chưa?","Báo cáo đã dùng động từ quá khứ (put, saw, waited...) chưa?","Bạn đã giải thích vì sao có giọt nước ngoài cốc chưa?","Một điều mình làm tốt: ______","Một điều mình muốn sửa: ______"]},{"step_no":14,"activity_type":"ACT-REVISE","mode":"REVISION","purpose":[],"target_ids":["A-A3-REDRAFT"],"prompt_en":"Read each hint, fix your report, underline what you changed, and write 'Mình đã đổi ... thành ... vì ...'.","time_min":15,"planned_date":"2026-10-30","items":[],"self_check_vi":[]}],"sources":[{"id":"A-W2-WATERCYCLE-S1","version":1,"title":"The Never-Ending Journey of Water (bài đọc WAT-R)","modality":"text","url":null},{"id":"A-W2-WATERCYCLE-S2","version":1,"title":"Mai and the cold glass (bài nghe WAT-L, file A_WAT_L)","modality":"audio","url":null}]}]$j$::jsonb) as r
on conflict (id, version) do nothing;

insert into english.template_item_keys(template_id, template_version, item_id, step_no, kind, answer, explanation_vi)
select 'A-W2-WATERCYCLE', 1, r->>'item_id', (r->>'step_no')::int, r->>'kind', r->>'answer', r->>'explanation_vi'
from jsonb_array_elements($j$[{"step_no":1,"item_id":"step-1:note","kind":"note","answer":null,"explanation_vi":"T2 26/10 (10') - Câu hỏi lớn, đoán trước, nhắc mẹo nói tiếp khi quên từ."},{"step_no":2,"item_id":"W2-L1","kind":"answer","answer":"b","explanation_vi":"Ý chính (c1)."},{"step_no":2,"item_id":"W2-L2","kind":"sealed","answer":"Very hot (and the air felt wet). Chấp nhận \"hot\".","explanation_vi":"Chi tiết 1/4."},{"step_no":2,"item_id":"W2-L3","kind":"sealed","answer":"That the glass had a hole.","explanation_vi":"Chi tiết 2/4."},{"step_no":2,"item_id":"W2-L4","kind":"sealed","answer":"Water vapour.","explanation_vi":"Chi tiết 3/4."},{"step_no":2,"item_id":"W2-L5","kind":"sealed","answer":"It cooled down and changed into tiny drops of water.","explanation_vi":"Chi tiết 4/4. Cần >= 3/4."},{"step_no":2,"item_id":"W2-L6","kind":"sealed","answer":"Nước trong cốc không vơi đi; nếu thủng thì nước bên trong phải giảm.","explanation_vi":"CHẨN ĐOÁN (suy luận)."},{"step_no":2,"item_id":"step-2:note","kind":"note","answer":null,"explanation_vi":"T2 26/10 (13') - Bài nghe làm TRONG buổi cô. Cô quan sát: An không xem chữ, số lần nghe."},{"step_no":3,"item_id":"step-3:note","kind":"note","answer":null,"explanation_vi":"T2 26/10 (12' + 10') - Âm cuối -s/-ed với động từ quen thuộc, khác chủ đề; rồi giới thiệu thí nghiệm cốc lạnh. KHÔNG phát 8 cụm từ ở T2 (nghĩa và câu ví dụ trùng đáp án bài đọc/nghe)."},{"step_no":4,"item_id":"W2-R1","kind":"answer","answer":"b","explanation_vi":"Ý chính (c1)."},{"step_no":4,"item_id":"W2-R2","kind":"sealed","answer":"The Sun.","explanation_vi":"Chi tiết 1/5."},{"step_no":4,"item_id":"W2-R3","kind":"sealed","answer":"Liquid water changing into a gas (water vapour).","explanation_vi":"Chi tiết 2/5."},{"step_no":4,"item_id":"W2-R4","kind":"sealed","answer":"Because the air high in the sky is cold.","explanation_vi":"Chi tiết 3/5 (nhân quả)."},{"step_no":4,"item_id":"W2-R5","kind":"sealed","answer":"C, B, E, A, D","explanation_vi":"Chi tiết 4/5 (trình tự)."},{"step_no":4,"item_id":"W2-R6","kind":"sealed","answer":"They become too heavy to stay in the air.","explanation_vi":"Chi tiết 5/5 (nhân quả). Cần >= 4/5."},{"step_no":4,"item_id":"W2-R7","kind":"sealed","answer":"Hơi thở có hơi nước ấm; không khí lạnh làm hơi nước nguội, ngưng tụ thành giọt rất nhỏ nên nhìn thấy được (đoạn 3).","explanation_vi":"CHẨN ĐOÁN (suy luận áp dụng). Có \"winter\" vì cuối tháng 10 Hà Nội thường chưa đủ lạnh để thấy hơi thở."},{"step_no":4,"item_id":"W2-R8","kind":"sealed","answer":"Goes slowly into (thấm vào).","explanation_vi":"CHẨN ĐOÁN (nghĩa từ)."},{"step_no":4,"item_id":"step-4:note","kind":"note","answer":null,"explanation_vi":"T3 27/10 (28') - Đặt hai cốc trước (3'; A: đá + nước; B: nước thường, cốc thủy tinh lau khô), để yên ít nhất 10 phút không chạm; trong lúc chờ An LÀM BÀI ĐỌC (18') ở bàn khác; rồi quan sát cốc với bố/mẹ (7'): mặt ngoài, sờ thử, nhìn khăn giấy, nói điều mình thấy. Không ghi chép mang vào T6."},{"step_no":5,"item_id":"W2-CV","kind":"sealed","answer":"Mặt Trời làm nóng nước -> nước bốc hơi thành hơi nước -> hơi nước bay lên, gặp lạnh -> ngưng tụ thành giọt nhỏ -> mây -> giọt nhập lại, nặng -> mưa -> sông, biển, đất -> lặp lại. Cốc nước đá = bước ngưng tụ.","explanation_vi":"Luyện tập, tùy chọn."},{"step_no":5,"item_id":"step-5:note","kind":"note","answer":null,"explanation_vi":"T4 28/10 (6' + 12') - Làm đầu tiên: phát 8 cụm từ + thẻ từ (6'), SAU khi An nộp bài nghe và bài đọc. Rồi Canvas (12'). 8 cụm từ: evaporate/evaporation = bốc hơi · water vapour = hơi nước · condense/condensation = ngưng tụ · tiny drops = giọt rất nhỏ · form a cloud / clouds form = tạo thành mây · fall as rain = rơi xuống thành mưa · heat from the Sun = sức nóng của Mặt Trời · that's why = vì thế mà. Đáp án gợi ý: Mặt Trời làm nóng nước -> nước bốc hơi thành hơi nước -> hơi nước bay lên, gặp lạnh -> ngưng tụ thành giọt nhỏ -> mây -> giọt nhập lại, nặng -> mưa -> sông, biển, đất -> lặp lại. Cốc nước đá = bước ngưng tụ."},{"step_no":6,"item_id":"step-6:note","kind":"note","answer":null,"explanation_vi":"T4 28/10 (12') - Luyện nói có câu mẫu. support_used = frame."},{"step_no":7,"item_id":"step-7:note","kind":"note","answer":null,"explanation_vi":"T5 29/10 (18') - Luyện viết có câu mẫu. Chỉ ghi A-L2-CHUNKS nếu >= 60 từ."},{"step_no":8,"item_id":"step-8:note","kind":"note","answer":null,"explanation_vi":"T5 29/10 (5' + 2' thẻ từ)."},{"step_no":9,"item_id":"W2-SIC","kind":"sealed","answer":"Mặt Trời làm nóng nước -> nước bốc hơi thành hơi nước -> hơi nước bay lên, gặp lạnh -> ngưng tụ thành giọt nhỏ -> mây -> giọt nhập lại, nặng -> mưa -> sông, biển, đất -> lặp lại. Cốc nước đá = bước ngưng tụ.","explanation_vi":"A-L3-CAUSE-S; A-L4-PROCESS-S (>= 3 bước đúng thứ tự); A-T4-CAUSE (chuỗi); A-L2-CHUNKS (>= 4/8 cụm)."},{"step_no":9,"item_id":"step-9:note","kind":"note","answer":null,"explanation_vi":"T6 30/10 (7') - Nói tự làm (SIC), kiểm tra trong buổi, ghi âm. Ghi activity_type = ACT-SPEAK-MONO. Nói trôi chảy và Xoay xở khi thiếu từ được chấm ở lượt LIVE kế tiếp."},{"step_no":10,"item_id":"W2-LIVE","kind":"sealed","answer":"Không có đáp án mẫu. Cô ghi: vật An chọn, từ An chưa biết, cách An diễn đạt vòng (a thing that..., it is like...), có chuyển sang tiếng Việt không.","explanation_vi":"A-X1-TURN (c1 >= 60 giây; c2 <= 3 lần ngừng dài; c3 nói lại câu) và A-L2-COMPENSATE-S (c1 >= 1 lần diễn đạt vòng thành công bằng tiếng Anh; c2 <= 1 lần chuyển sang tiếng Việt), hoặc NULL."},{"step_no":10,"item_id":"step-10:note","kind":"note","answer":null,"explanation_vi":"T6 30/10 (4') - Lượt nói trực tiếp (kit mục 3.0, \"Thử thách thiếu từ\"). Cô đưa 3 ảnh: sponge (miếng bọt biển) · tape measure (thước dây) · ladder (cái thang). Cô không nói tên tiếng Anh trước T6; cô chỉ nói \"Bắt đầu nhé\" / \"Còn 30 giây\", không nhắc \"giải thích cách khác\". Ghi activity_type = ACT-SPEAK-LIVE, context_topic = lab-tools, chỉ cô chấm; cô bấm giờ (duration_s; c1 Nói trôi chảy cần >= 60 giây). Nói trôi chảy: c1 >= 60 giây, c2 <= 3 lần ngừng > 3 giây, c3 nói lại câu thay vì bỏ dở. Xoay xở khi thiếu từ: cô xác nhận có chỗ thiếu từ thật; An biết tên cả 3 vật (đổi bộ ảnh) hoặc không có chỗ thiếu thật => NULL, đó là kết quả hợp lệ."},{"step_no":11,"item_id":"W2-OP","kind":"sealed","answer":"Không có đáp án đúng/sai; chấm lập luận.","explanation_vi":"A-T7-OPINION: c1 quan điểm rõ; c2 >= 2 lý do khác nhau, liên quan; c3 >= 1 ví dụ gắn với một lý do."},{"step_no":11,"item_id":"step-11:note","kind":"note","answer":null,"explanation_vi":"T6 30/10 (3') - Nói ý kiến (OP), ghi âm trên máy. Cô hỏi một lần, nghĩ 30 giây, không hỏi thêm \"Why?\" khi An đang nói; An nói ít nhất 1 phút. Chấm: c1 quan điểm rõ, c2 >= 2 lý do khác nhau, c3 >= 1 ví dụ gắn với lý do. Không chấm quan điểm đúng/sai. Ghi activity_type = ACT-SPEAK-MONO (catalogue không nhận Nêu ý kiến ở ACT-SPEAK-LIVE). Sau đó: \"Now ask me two questions about rain or clouds.\" (chỉ ghi chú, không ghi dòng)."},{"step_no":12,"item_id":"W2-WIC","kind":"sealed","answer":"Kể quá khứ: đã làm gì, thấy gì; giải thích: hơi nước trong không khí gặp cốc lạnh -> nguội -> ngưng tụ thành giọt.","explanation_vi":"A-L1-PAST-W c1-c2; A-L3-CAUSE-W; A-L3-PARA-W; A-T4-CAUSE; A-L2-CHUNKS."},{"step_no":12,"item_id":"step-12:note","kind":"note","answer":null,"explanation_vi":"T6 30/10 (20') - Viết tự làm, kiểm tra trong buổi. Đếm chỗ bắt buộc dùng quá khứ (put, waited, saw, was, touched...): < 6 chỗ hoặc < 80 từ => A-L1-PAST-W = NULL."},{"step_no":13,"item_id":"step-13:note","kind":"note","answer":null,"explanation_vi":"T6 30/10 (3'). Tự kiểm: 1 bạn làm gì -> bạn thấy gì; 2 động từ quá khứ (put, saw, waited); 3 giải thích vì sao có giọt nước ngoài cốc."},{"step_no":14,"item_id":"step-14:note","kind":"note","answer":null,"explanation_vi":"T6 30/10 (7' + 15') - Thêm: đọc to từng câu có động từ; chuyện đã xảy ra thì động từ đã ở quá khứ chưa?"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W2-WATERCYCLE' and it.version = 1 and it.published_at is not null)
on conflict (template_id, template_version, item_id) do nothing;

update english.inquiry_templates set status = 'published', published_at = now()
where id = 'A-W2-WATERCYCLE' and version = 1 and published_at is null;

-- Inquiry template A-W3-EARTHQUAKES v1 (published after its sources and answer keys are in)
insert into english.sources(id, version, title, url, author, rights_note, modality, body, source_hash)
select r->>'id', (r->>'version')::int, r->>'title', r->>'url', r->>'author', r->>'rights_note', r->>'modality', r->>'body', r->>'source_hash'
from jsonb_array_elements($j$[{"id":"A-W3-EARTHQUAKES-S1","version":1,"title":"Why Does the Ground Shake? (bài đọc EQ-R)","url":null,"author":"Tự soạn cho Pilot Kit A v0.2.1 (phụ huynh/Claude); không phải trích từ sách hay đề thi - không nhắc núi lửa hay 'vành đai lửa' (giữ khoảng cách 14 ngày cho bài ôn núi lửa)","rights_note":"Tự soạn. Nguồn kiểm: USGS The Science of Earthquakes (https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes), USGS tốc độ mảng (https://www.usgs.gov/faqs/how-fast-do-tectonic-plates-move), USGS cường độ rung (https://www.usgs.gov/programs/earthquake-hazards/earthquake-magnitude-energy-release-and-shaking-intensity). Câu \"Many earthquakes are very small…\" chưa có trang USGS nêu thẳng; phụ huynh tìm \"too small to be felt\" trên USGS trước khi giao.","modality":"text","body":"Why Does the Ground Shake?\n\nThe ground under our feet feels still. But the outside of the Earth is not one solid piece. It is broken into huge pieces called plates, like the cracked shell of a boiled egg.\n\nThe plates move very slowly, about as fast as your fingernails grow. Some plates move apart, some push into each other, and some slide past each other.\n\nThe edges of the plates are rough, so they often get stuck. The plates keep pushing, but the edges cannot move. Energy builds up in the rocks, like a ruler that you bend more and more. Then, suddenly, the rocks slip, like the ruler springing back. The stored energy travels out in all directions as waves. These are called seismic waves. When the waves reach the surface, the ground shakes. This is an earthquake.\n\nThe crack where the rocks slip is called a fault. The place on the surface right above the start of the earthquake is called the epicentre. The shaking is usually strongest near the epicentre.\n\nMany earthquakes are very small, and people do not feel them. After a big earthquake, smaller ones called aftershocks often follow.","source_hash":"1340e2dad23981f1b2b2d39436d461e5f846e4df6fa0f9ca5ddd5d69ece1bd04"},{"id":"A-W3-EARTHQUAKES-S2","version":1,"title":"Drop, Cover, Hold On (bài nghe EQ-L, file A_EQ_L)","url":null,"author":"Tự soạn cho Pilot Kit A v0.2.1 (phụ huynh/Claude); không phải trích từ sách hay đề thi","rights_note":"Tự soạn, TTS một giọng cố định 0,9x. Nguồn kiểm: CDC (https://cdc.gov/earthquakes/safety/stay-safe-during-an-earthquake.html): drop, cover, hold on; không chạy ra ngoài; không đứng ở khung cửa; tránh kính; ra chỗ trống.","modality":"audio","body":null,"source_hash":"e8108a22cff3be8cb7f2b32866d6f0b4dc0867c9586864f742dabc1081411852"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W3-EARTHQUAKES' and it.version = 1 and it.published_at is not null)
on conflict (id, version) do nothing;

insert into english.source_transcripts(source_id, source_version, transcript)
select r->>'id', (r->>'version')::int, r->>'transcript'
from jsonb_array_elements($j$[{"id":"A-W3-EARTHQUAKES-S2","version":1,"transcript":"What should you do if the ground starts to shake? Remember three words: Drop, Cover, Hold On.\n\nFirst, drop down onto your hands and knees. This stops you from falling over.\n\nNext, cover your head and neck with your arms. If there is a strong table or desk near you, get under it. Things can fall from shelves and walls, so protect your head.\n\nThen, hold on to the table and stay there until the shaking stops.\n\nDo not run outside while the ground is shaking, and do not stand in a doorway. Stay away from windows, because the glass can break.\n\nIf you are outside, move to an open place, away from buildings, trees and electric wires. Then drop down and stay there.\n\nWhen the shaking stops, wait for an adult to tell you what to do next."}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W3-EARTHQUAKES' and it.version = 1 and it.published_at is not null)
on conflict (source_id, source_version) do nothing;

update english.sources set published_at = now()
where version = 1 and id in ('A-W3-EARTHQUAKES-S1', 'A-W3-EARTHQUAKES-S2') and published_at is null;

insert into english.inquiry_templates(id, version, track_id, title_vi, big_question_en, big_question_vi, week, date_from, date_to, domain_bucket, target_ids, steps, sources, catalogue_version, status, source_hash)
select r->>'id', (r->>'version')::int, r->>'track_id', r->>'title_vi', r->>'big_question_en', r->>'big_question_vi', (r->>'week')::int,
  (r->>'date_from')::date, (r->>'date_to')::date, r->>'domain_bucket',
  array(select e from jsonb_array_elements_text(r->'target_ids') with ordinality as t(e, n) order by n), r->'steps', r->'sources', '0.2.1-draft', 'draft', 'c99e5eefddd3b4610fe6f1828dd1f6dbd152f82c0bbdea5b836dd0183f8b9177'
from jsonb_array_elements($j$[{"id":"A-W3-EARTHQUAKES","version":1,"track_id":"A","title_vi":"Tuần 3 - Động đất (có bài ôn núi lửa sau 14 ngày)","big_question_en":"Why does the ground shake?","big_question_vi":"Vì sao mặt đất rung lên?","week":3,"date_from":"2026-11-02","date_to":"2026-11-08","domain_bucket":"science","target_ids":["A-T1-TEXT-L","A-T1-TEXT-R","A-L3-CAUSE-S","A-L3-CAUSE-W","A-L3-PARA-W","A-L4-PROCESS-S","A-L1-PAST-W","A-L2-CHUNKS","A-L2-COMPENSATE-S","A-T4-CAUSE","A-T7-OPINION","A-X1-TURN"],"steps":[{"step_no":1,"activity_type":"ACT-SPEAK-LIVE","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Why does the ground shake? (You can speak Vietnamese.) Do not talk about volcanoes this week - if An asks, say: 'We will talk about that on Friday.'","time_min":8,"planned_date":"2026-11-02","items":[],"self_check_vi":[]},{"step_no":2,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-T1-TEXT-R"],"prompt_en":"Read the text once, then answer. You may look back at the text. No dictionary.","time_min":18,"planned_date":"2026-11-02","items":[{"id":"W3-R1","kind":"mcq","stem":"What is the text mainly about?","options":["a) how to stay safe in an earthquake","b) why earthquakes happen","c) how fast fingernails grow","d) why boiled eggs crack"],"target_id":"A-T1-TEXT-R"},{"id":"W3-R2","kind":"short","stem":"What are plates?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W3-R3","kind":"short","stem":"How fast do plates move?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W3-R4","kind":"short","stem":"Why do the edges of the plates often get stuck?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W3-R5","kind":"short","stem":"Put in order: (A) the rocks suddenly slip (B) energy builds up in the rocks (C) the edges get stuck (D) the ground shakes","options":["A","B","C","D"],"target_id":"A-T1-TEXT-R"},{"id":"W3-R6","kind":"short","stem":"Where is the shaking usually strongest?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W3-R7","kind":"open","stem":"Two towns feel the same earthquake. Town A is 5 km from the epicentre. Town B is 200 km away. Which town probably feels stronger shaking? Why?","options":[],"target_id":"A-T2-INFER-R"},{"id":"W3-R8","kind":"short","stem":"\"...the rocks slip.\" What does 'slip' mean here?","options":[],"target_id":"A-T2-INFER-R"}],"self_check_vi":[]},{"step_no":3,"activity_type":"ACT-SPEAK-LIVE","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Tip for a missing word: It's a kind of... / It's like... / It's a thing that... (practise with two objects that are not in the Friday picture set). Then: this week you will practise speaking and writing about earthquakes.","time_min":19,"planned_date":"2026-11-02","items":[],"self_check_vi":[]},{"step_no":4,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["A-T1-TEXT-L"],"prompt_en":"Listen (maximum 2 times, no text). Answer the questions.","time_min":25,"planned_date":"2026-11-03","items":[{"id":"W3-L1","kind":"mcq","stem":"What is the talk mainly about?","options":["a) why earthquakes happen","b) what to do to stay safe when the ground shakes","c) how to build strong tables","d) why windows break"],"target_id":"A-T1-TEXT-L"},{"id":"W3-L2","kind":"short","stem":"What should you do first?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W3-L3","kind":"short","stem":"What should you cover with your arms?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W3-L4","kind":"short","stem":"Why should you stay away from windows?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W3-L5","kind":"short","stem":"If you are outside, where should you go?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W3-L6","kind":"open","stem":"Why does the speaker tell you to get under a strong table?","options":[],"target_id":"A-T2-INFER-L"}],"self_check_vi":[]},{"step_no":5,"activity_type":"ACT-CANVAS-BASIC","mode":"PRACTICE","purpose":[],"target_ids":["A-T4-CAUSE"],"prompt_en":"Main idea: Earthquakes happen when... Why (4 cards): [Plates move, but the edges...] -> [Energy...] -> [Suddenly,...] -> [Seismic waves..., so...]. Example: the ruler - you bend it and let it go. Which step is that?","time_min":12,"planned_date":"2026-11-04","items":[{"id":"W3-CV","kind":"open","stem":"Fill in the 4 cards and the example.","options":[],"target_id":"A-T4-CAUSE"}],"self_check_vi":[]},{"step_no":6,"activity_type":"ACT-SPEAK-MONO","mode":"PRACTICE","purpose":[],"target_ids":["A-L3-CAUSE-S","A-L2-CHUNKS"],"prompt_en":"What should you do if an earthquake happens? Why? - First,..., because... / Next,... This is important because... / Do not..., because... / If you are outside,... (45-60 seconds)","time_min":12,"planned_date":"2026-11-04","items":[],"self_check_vi":[]},{"step_no":7,"activity_type":"ACT-WRITE","mode":"PRACTICE","purpose":[],"target_ids":["A-L3-CAUSE-W","A-L2-CHUNKS"],"prompt_en":"What are plates, and why do their edges get stuck? - The outside of the Earth is... / The plates move..., about as fast as... / The edges of the plates are..., so... / Energy builds up because... (50-70 words)","time_min":18,"planned_date":"2026-11-05","items":[],"self_check_vi":[]},{"step_no":8,"activity_type":"ACT-SELF-REVIEW","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Check your own writing.","time_min":7,"planned_date":"2026-11-05","items":[],"self_check_vi":["Bạn đã nói vì sao mép các mảng bị kẹt chưa?","Bạn đã kể đủ: kẹt -> tích năng lượng -> trượt -> rung chưa?","Câu cuối của bạn đã kết lại ý chưa?"]},{"step_no":9,"activity_type":"ACT-SPEAK-MONO","mode":"INDEPENDENT_CHECK","purpose":["delayed_check","checkpoint"],"target_ids":["A-L3-CAUSE-S","A-L4-PROCESS-S","A-T4-CAUSE"],"prompt_en":"A younger child asks you: 'Why do volcanoes erupt?' Explain it simply, step by step. (30 seconds to think, no notes. Speak 60-90 seconds.)","time_min":7,"planned_date":"2026-11-06","items":[{"id":"W3-VOLDEL","kind":"open","stem":"A younger child asks you: 'Why do volcanoes erupt?' Explain it simply, step by step.","options":[],"target_id":"A-L3-CAUSE-S"}],"self_check_vi":[]},{"step_no":10,"activity_type":"ACT-SPEAK-MONO","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-L3-CAUSE-S","A-L4-PROCESS-S","A-T4-CAUSE","A-L2-CHUNKS"],"prompt_en":"Why do earthquakes happen? Explain it step by step, from the plates to the shaking ground. (30 seconds to think. Speak 60-90 seconds.)","time_min":7,"planned_date":"2026-11-06","items":[{"id":"W3-SIC","kind":"open","stem":"Why do earthquakes happen? Explain step by step.","options":[],"target_id":"A-L3-CAUSE-S"}],"self_check_vi":[]},{"step_no":11,"activity_type":"ACT-SPEAK-LIVE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-X1-TURN","A-L2-COMPENSATE-S"],"prompt_en":"Choose one picture. It must be something you know how to use, but you do not know its English name. Tell me about it: what it looks like, what we use it for, and how you use it. (30 seconds to think, no writing. Speak 60-90 seconds.)","time_min":4,"planned_date":"2026-11-06","items":[{"id":"W3-LIVE","kind":"open","stem":"Choose one picture and tell me about it.","options":[],"target_id":"A-X1-TURN"}],"self_check_vi":[]},{"step_no":12,"activity_type":"ACT-SPEAK-MONO","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-T7-OPINION"],"prompt_en":"Should every school practise earthquake drills, even in places where earthquakes are rare? Why or why not? Give your reasons and an example. Talk for at least one minute. (Then: Now ask me two questions about earthquakes.)","time_min":3,"planned_date":"2026-11-06","items":[{"id":"W3-OP","kind":"open","stem":"Should every school practise earthquake drills, even in places where earthquakes are rare? Why or why not? Give your reasons and an example. Talk for at least one minute.","options":[],"target_id":"A-T7-OPINION"}],"self_check_vi":[]},{"step_no":13,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-L1-PAST-W","A-L3-CAUSE-W","A-L3-PARA-W","A-T4-CAUSE","A-L2-CHUNKS"],"prompt_en":"Imagine that yesterday, at school, you felt a very small earthquake. It lasted a few seconds, and nobody was hurt. Write your diary in one paragraph (80-120 words). What happened? What did you do? Why did the ground shake? (20 minutes.)","time_min":20,"planned_date":"2026-11-06","items":[{"id":"W3-WIC","kind":"open","stem":"Write your diary about a very small earthquake.","options":[],"target_id":"A-L1-PAST-W"}],"self_check_vi":[]},{"step_no":14,"activity_type":"ACT-SELF-REVIEW","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-A1-SELFASSESS"],"prompt_en":"Before you hear any feedback, check your own diary.","time_min":3,"planned_date":"2026-11-06","items":[],"self_check_vi":["Bạn đã nói vì sao mặt đất rung chưa?","Nhật ký của bạn kể chuyện hôm qua: các động từ đã ở quá khứ chưa?","Câu cuối của bạn đã kết lại ý chưa?","Một điều mình làm tốt: ______","Một điều mình muốn sửa: ______"]},{"step_no":15,"activity_type":"ACT-REVISE","mode":"REVISION","purpose":[],"target_ids":["A-A3-REDRAFT"],"prompt_en":"Read each hint, fix your diary, underline what you changed, and write 'Mình đã đổi ... thành ... vì ...'.","time_min":15,"planned_date":"2026-11-06","items":[],"self_check_vi":[]}],"sources":[{"id":"A-W3-EARTHQUAKES-S1","version":1,"title":"Why Does the Ground Shake? (bài đọc EQ-R)","modality":"text","url":null},{"id":"A-W3-EARTHQUAKES-S2","version":1,"title":"Drop, Cover, Hold On (bài nghe EQ-L, file A_EQ_L)","modality":"audio","url":null}]}]$j$::jsonb) as r
on conflict (id, version) do nothing;

insert into english.template_item_keys(template_id, template_version, item_id, step_no, kind, answer, explanation_vi)
select 'A-W3-EARTHQUAKES', 1, r->>'item_id', (r->>'step_no')::int, r->>'kind', r->>'answer', r->>'explanation_vi'
from jsonb_array_elements($j$[{"step_no":1,"item_id":"step-1:note","kind":"note","answer":null,"explanation_vi":"T2 2/11 (8') - Câu hỏi lớn. Cả tuần KHÔNG nhắc núi lửa (bài ôn 6/11). An lỡ nói về núi lửa => ghi Sổ tiếp xúc."},{"step_no":2,"item_id":"W3-R1","kind":"answer","answer":"b","explanation_vi":"Ý chính (c1)."},{"step_no":2,"item_id":"W3-R2","kind":"sealed","answer":"Huge pieces of the outside of the Earth.","explanation_vi":"Chi tiết 1/5."},{"step_no":2,"item_id":"W3-R3","kind":"sealed","answer":"Very slowly - about as fast as fingernails grow.","explanation_vi":"Chi tiết 2/5."},{"step_no":2,"item_id":"W3-R4","kind":"sealed","answer":"Because they are rough.","explanation_vi":"Chi tiết 3/5 (nhân quả)."},{"step_no":2,"item_id":"W3-R5","kind":"sealed","answer":"C, B, A, D","explanation_vi":"Chi tiết 4/5 (trình tự)."},{"step_no":2,"item_id":"W3-R6","kind":"sealed","answer":"Near the epicentre.","explanation_vi":"Chi tiết 5/5. Cần >= 4/5."},{"step_no":2,"item_id":"W3-R7","kind":"sealed","answer":"Town A - it is nearer to the epicentre, and the text says the shaking is usually strongest there.","explanation_vi":"CHẨN ĐOÁN (suy luận ứng dụng)."},{"step_no":2,"item_id":"W3-R8","kind":"sealed","answer":"Move suddenly (trượt đi bất ngờ).","explanation_vi":"CHẨN ĐOÁN (nghĩa từ)."},{"step_no":2,"item_id":"step-2:note","kind":"note","answer":null,"explanation_vi":"T2 2/11 (18') - Bài đọc làm TRONG buổi cô. An làm một mình."},{"step_no":3,"item_id":"step-3:note","kind":"note","answer":null,"explanation_vi":"T2 2/11 (10' + 5' + 4') - Mẹo nói tiếp khi quên từ (luyện với 2 vật khác bộ ảnh T6), giao việc. KHÔNG phát 8 cụm từ ở T2: nghĩa và câu ví dụ trùng đáp án bài đọc/nghe."},{"step_no":4,"item_id":"W3-L1","kind":"answer","answer":"b","explanation_vi":"Ý chính (c1)."},{"step_no":4,"item_id":"W3-L2","kind":"sealed","answer":"Drop down onto your hands and knees (chấp nhận 'Drop').","explanation_vi":"Chi tiết 1/4."},{"step_no":4,"item_id":"W3-L3","kind":"sealed","answer":"Your head and neck.","explanation_vi":"Chi tiết 2/4."},{"step_no":4,"item_id":"W3-L4","kind":"sealed","answer":"The glass can break.","explanation_vi":"Chi tiết 3/4 (nhân quả)."},{"step_no":4,"item_id":"W3-L5","kind":"sealed","answer":"An open place, away from buildings, trees and electric wires.","explanation_vi":"Chi tiết 4/4. Cần >= 3/4."},{"step_no":4,"item_id":"W3-L6","kind":"sealed","answer":"Bàn chắc che đầu và cổ khỏi đồ rơi ('Things can fall... so protect your head').","explanation_vi":"CHẨN ĐOÁN (suy luận)."},{"step_no":4,"item_id":"step-4:note","kind":"note","answer":null,"explanation_vi":"T3 3/11 (25') - Bài nghe ở nhà (10'), sau đó tập 'Drop, Cover, Hold On' bằng động tác (5'; chỉ làm SAU khi đã nộp bài nghe). CUỐI T3, sau khi nộp cả bài đọc và bài nghe: phát 8 cụm từ + thẻ từ (10'). 8 cụm từ: plates = các mảng · move slowly = di chuyển chậm · get stuck = bị kẹt · energy builds up = năng lượng tích tụ · suddenly slip = đột ngột trượt · seismic waves = sóng địa chấn · the ground shakes = mặt đất rung · because of = vì, do."},{"step_no":5,"item_id":"W3-CV","kind":"sealed","answer":"Mảng di chuyển -> mép gồ ghề bị kẹt -> năng lượng tích tụ trong đá -> đá đột ngột trượt (đứt gãy) -> năng lượng lan ra thành sóng địa chấn -> sóng tới mặt đất -> rung.","explanation_vi":"Luyện tập, tùy chọn."},{"step_no":5,"item_id":"step-5:note","kind":"note","answer":null,"explanation_vi":"T4 4/11 (12'). Đáp án gợi ý: Mảng di chuyển -> mép gồ ghề bị kẹt -> năng lượng tích tụ trong đá -> đá đột ngột trượt (đứt gãy) -> năng lượng lan ra thành sóng địa chấn -> sóng tới mặt đất -> rung. Thước: uốn = tích năng lượng; bật lại = đá trượt."},{"step_no":6,"item_id":"step-6:note","kind":"note","answer":null,"explanation_vi":"T4 4/11 (12') - Luyện nói có câu mẫu. support_used = frame."},{"step_no":7,"item_id":"step-7:note","kind":"note","answer":null,"explanation_vi":"T5 5/11 (18'). Hỏi An trước (T5) có ổn với đề nhật ký động đất không."},{"step_no":8,"item_id":"step-8:note","kind":"note","answer":null,"explanation_vi":"T5 5/11 (5' + 2')."},{"step_no":9,"item_id":"W3-VOLDEL","kind":"sealed","answer":"Magma nhẹ hơn đá -> nổi lên, gom trong buồng magma -> gần mặt đất áp suất giảm -> khí thoát ra thành bong bóng -> bong bóng lớn dần, đẩy magma -> magma xuyên qua mặt đất = phun trào. Magma loãng: khí thoát dễ -> dung nham chảy. Magma đặc: khí bị giữ -> áp suất tăng -> nổ.","explanation_vi":"A-L3-CAUSE-S; A-L4-PROCESS-S; A-T4-CAUSE (nhớ chuỗi sau 14 ngày)."},{"step_no":9,"item_id":"step-9:note","kind":"note","answer":null,"explanation_vi":"T6 6/11, LÀM ĐẦU TIÊN (7') - Bài ôn núi lửa VOL-DEL. Hợp lệ khi ngày ôn - ngày tiếp xúc cuối >= 14: 6/11 - 23/10 = 14. last_practice_date = 2026-10-23. Chỉ làm nếu Sổ tiếp xúc không ghi lần gặp núi lửa nào từ 24/10; nếu có, dời sang >= 14 ngày sau lần đó (vd. T2 9/11 = 17 ngày). Ghi thêm (chẩn đoán): An dùng lại đúng mấy trong 8 cụm từ tuần 1."},{"step_no":10,"item_id":"W3-SIC","kind":"sealed","answer":"Mảng di chuyển -> mép gồ ghề bị kẹt -> năng lượng tích tụ trong đá -> đá đột ngột trượt (đứt gãy) -> năng lượng lan ra thành sóng địa chấn -> sóng tới mặt đất -> rung.","explanation_vi":"A-L3-CAUSE-S; A-L4-PROCESS-S; A-T4-CAUSE; A-L2-CHUNKS."},{"step_no":10,"item_id":"step-10:note","kind":"note","answer":null,"explanation_vi":"T6 6/11 (7') - Nói tự làm (SIC), kiểm tra trong buổi, ghi âm. Ghi activity_type = ACT-SPEAK-MONO. Nói trôi chảy và Xoay xở khi thiếu từ được chấm ở lượt LIVE kế tiếp."},{"step_no":11,"item_id":"W3-LIVE","kind":"sealed","answer":"Không có đáp án mẫu. Cô ghi: vật An chọn, từ An chưa biết, cách An diễn đạt vòng (a thing that..., it is like...), có chuyển sang tiếng Việt không.","explanation_vi":"A-X1-TURN (c1 >= 60 giây; c2 <= 3 lần ngừng dài; c3 nói lại câu) và A-L2-COMPENSATE-S (c1 >= 1 lần diễn đạt vòng thành công bằng tiếng Anh; c2 <= 1 lần chuyển sang tiếng Việt), hoặc NULL."},{"step_no":11,"item_id":"step-11:note","kind":"note","answer":null,"explanation_vi":"T6 6/11 (4') - Lượt nói trực tiếp (kit mục 3.0, \"Thử thách thiếu từ\"). Cô đưa 3 ảnh: whistle (cái còi) · first-aid kit (hộp sơ cứu) · fire extinguisher (bình chữa cháy). Cô không nói tên tiếng Anh trước T6; cô chỉ nói \"Bắt đầu nhé\" / \"Còn 30 giây\", không nhắc \"giải thích cách khác\". Ghi activity_type = ACT-SPEAK-LIVE, context_topic = lab-tools, chỉ cô chấm; cô bấm giờ (duration_s; c1 Nói trôi chảy cần >= 60 giây). Nói trôi chảy: c1 >= 60 giây, c2 <= 3 lần ngừng > 3 giây, c3 nói lại câu thay vì bỏ dở. Xoay xở khi thiếu từ: cô xác nhận có chỗ thiếu từ thật; An biết tên cả 3 vật (đổi bộ ảnh) hoặc không có chỗ thiếu thật => NULL, đó là kết quả hợp lệ."},{"step_no":12,"item_id":"W3-OP","kind":"sealed","answer":"Không có đáp án đúng/sai; chấm lập luận.","explanation_vi":"A-T7-OPINION: c1 quan điểm rõ; c2 >= 2 lý do khác nhau, liên quan; c3 >= 1 ví dụ gắn với một lý do."},{"step_no":12,"item_id":"step-12:note","kind":"note","answer":null,"explanation_vi":"T6 6/11 (3') - Nói ý kiến (OP), ghi âm trên máy. Cô hỏi một lần, nghĩ 30 giây, không hỏi thêm \"Why?\" khi An đang nói; An nói ít nhất 1 phút. Chấm: c1 quan điểm rõ, c2 >= 2 lý do khác nhau, c3 >= 1 ví dụ gắn với lý do. Không chấm quan điểm đúng/sai. Ghi activity_type = ACT-SPEAK-MONO (catalogue không nhận Nêu ý kiến ở ACT-SPEAK-LIVE). Sau đó: \"Now ask me two questions about earthquakes.\" (chỉ ghi chú, không ghi dòng)."},{"step_no":13,"item_id":"W3-WIC","kind":"sealed","answer":"Kể quá khứ + giải thích: mảng kẹt -> tích năng lượng -> trượt -> sóng -> rung.","explanation_vi":"A-L1-PAST-W; A-L3-CAUSE-W; A-L3-PARA-W; A-T4-CAUSE; A-L2-CHUNKS."},{"step_no":13,"item_id":"step-13:note","kind":"note","answer":null,"explanation_vi":"T6 6/11 (20') - Viết tự làm. Đề thay thế nếu An lo: 'Yesterday your class had an earthquake drill. Write your diary in one paragraph (80-120 words): what did you do, and why do earthquakes happen?' (ghi đề đã dùng vào notes). < 6 chỗ bắt buộc dùng quá khứ hoặc < 80 từ => NULL."},{"step_no":14,"item_id":"step-14:note","kind":"note","answer":null,"explanation_vi":"T6 6/11 (3')."},{"step_no":15,"item_id":"step-15:note","kind":"note","answer":null,"explanation_vi":"T6 6/11 (7' + 15') - Thêm: gạch dưới mọi động từ trong nhật ký; chuyện hôm qua thì động từ ở quá khứ."}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W3-EARTHQUAKES' and it.version = 1 and it.published_at is not null)
on conflict (template_id, template_version, item_id) do nothing;

update english.inquiry_templates set status = 'published', published_at = now()
where id = 'A-W3-EARTHQUAKES' and version = 1 and published_at is null;

-- Inquiry template A-W4-PLANETS v1 (published after its sources and answer keys are in)
insert into english.sources(id, version, title, url, author, rights_note, modality, body, source_hash)
select r->>'id', (r->>'version')::int, r->>'title', r->>'url', r->>'author', r->>'rights_note', r->>'modality', r->>'body', r->>'source_hash'
from jsonb_array_elements($j$[{"id":"A-W4-PLANETS-S1","version":1,"title":"Venus: Earth's Hot Twin (bài đọc PLA-R)","url":null,"author":"Tự soạn cho Pilot Kit A v0.2.1 (phụ huynh/Claude); không phải trích từ sách hay đề thi - chỉ nhắc 'clouds made of acid', không giải thích mây hình thành (giữ khoảng cách 14 ngày cho bài ôn nước)","rights_note":"Tự soạn. Nguồn kiểm: NASA Venus Facts (https://science.nasa.gov/venus/venus-facts/): 467 độ C, khí quyển chủ yếu CO2, áp suất 93 lần, mây axit sunfuric, quay ngược, 243 ngày quay so với 225 ngày quỹ đạo, không có mặt trăng; Physics Today (https://physicstoday.aip.org/opinion/venus-is-not-earths-closest-neighbor): Sao Kim chỉ gần nhất khi tiến sát nhất.","modality":"text","body":"Venus: Earth's Hot Twin\n\nVenus is the second planet from the Sun. At its closest, Venus comes nearer to Earth than any other planet, and it is almost the same size as Earth. That is why people sometimes call it Earth's twin. But Venus is a terrible place to visit.\n\nVenus is the hottest planet in our Solar System. The temperature on its surface is about 465 degrees Celsius. That is hot enough to melt some metals! Mercury is closer to the Sun, but Venus is hotter. Why?\n\nThe answer is its atmosphere. The air on Venus is very thick, and it is mostly carbon dioxide. This thick air traps the heat from the Sun, like a heavy blanket. The heat cannot escape, so the planet stays extremely hot, day and night.\n\nThe air on Venus is also very heavy. If you stood on Venus, the air would press on you more than 90 times harder than the air on Earth. Its thick clouds are made of acid, too.\n\nVenus spins very slowly, and it spins in the opposite direction from most planets. One day on Venus is longer than one year there! Venus has no moons.","source_hash":"1a280dc3a34656c4aef75c9552baae6d18934db102be3ccdb5ce5c2cf0000b8a"},{"id":"A-W4-PLANETS-S2","version":1,"title":"Mars (bài nghe PLA-L, file A_PLA_L)","url":null,"author":"Tự soạn cho Pilot Kit A v0.2.1 (phụ huynh/Claude); không phải trích từ sách hay đề thi","rights_note":"Tự soạn, TTS một giọng cố định 0,9x. Nguồn kiểm: NASA Mars Facts (https://science.nasa.gov/mars/facts/): nửa Trái Đất, đỏ vì sắt gỉ, 20 độ C xuống -153 độ C, ngày 24,6 giờ, năm 687 ngày, hai mặt trăng; NASA JPL Mars in a Minute (https://www.jpl.nasa.gov/edu/resources/video/mars-in-a-minute-is-mars-red-hot/): xa Mặt Trời hơn, khí quyển mỏng ~100 lần.","modality":"audio","body":null,"source_hash":"414416115e067fead046354fbb332c7941be5affef0906e3625e1fd57905979c"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W4-PLANETS' and it.version = 1 and it.published_at is not null)
on conflict (id, version) do nothing;

insert into english.source_transcripts(source_id, source_version, transcript)
select r->>'id', (r->>'version')::int, r->>'transcript'
from jsonb_array_elements($j$[{"id":"A-W4-PLANETS-S2","version":1,"transcript":"Mars is the fourth planet from the Sun. It is about half the size of Earth. Mars looks red because its rocks and dust have iron in them, and the iron has rusted.\n\nMars is much colder than Earth, and there are two reasons. First, Mars is farther from the Sun, so it gets less heat. Second, its atmosphere is very thin. Thin air cannot hold the heat, so the heat escapes into space. The temperature can go from about 20 degrees Celsius on a summer afternoon down to about minus 150 degrees in the coldest places.\n\nA day on Mars is a little longer than a day on Earth, about 24 and a half hours. But a year on Mars is almost two Earth years long. Mars has two small moons, called Phobos and Deimos.\n\nScientists have sent robots to explore Mars, but no person has been there yet."}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W4-PLANETS' and it.version = 1 and it.published_at is not null)
on conflict (source_id, source_version) do nothing;

update english.sources set published_at = now()
where version = 1 and id in ('A-W4-PLANETS-S1', 'A-W4-PLANETS-S2') and published_at is null;

insert into english.inquiry_templates(id, version, track_id, title_vi, big_question_en, big_question_vi, week, date_from, date_to, domain_bucket, target_ids, steps, sources, catalogue_version, status, source_hash)
select r->>'id', (r->>'version')::int, r->>'track_id', r->>'title_vi', r->>'big_question_en', r->>'big_question_vi', (r->>'week')::int,
  (r->>'date_from')::date, (r->>'date_to')::date, r->>'domain_bucket',
  array(select e from jsonb_array_elements_text(r->'target_ids') with ordinality as t(e, n) order by n), r->'steps', r->'sources', '0.2.1-draft', 'draft', '88a9cc4d7fc9f280c8c9027d8babc0b94d6a39e7223792927d3fef0ff17251f1'
from jsonb_array_elements($j$[{"id":"A-W4-PLANETS","version":1,"track_id":"A","title_vi":"Tuần 4 - So sánh Sao Kim và Sao Hỏa (có bài ôn vòng tuần hoàn nước sau 14 ngày)","big_question_en":"How are Venus and Mars alike and different?","big_question_vi":"Sao Kim và Sao Hỏa giống và khác nhau thế nào?","week":4,"date_from":"2026-11-09","date_to":"2026-11-15","domain_bucket":"science","target_ids":["A-T1-TEXT-L","A-T1-TEXT-R","A-L3-CAUSE-S","A-L3-CAUSE-W","A-L3-PARA-W","A-L4-PROCESS-S","A-L2-CHUNKS","A-L2-COMPENSATE-S","A-T4-CAUSE","A-T7-OPINION","A-X1-TURN"],"steps":[{"step_no":1,"activity_type":"ACT-SPEAK-LIVE","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Which planet would you like to visit? (You can speak Vietnamese.) Tip for a missing word: It's a kind of... / It's like...","time_min":8,"planned_date":"2026-11-09","items":[],"self_check_vi":[]},{"step_no":2,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-T1-TEXT-L"],"prompt_en":"Listen (maximum 2 times, no text). Answer the questions.","time_min":13,"planned_date":"2026-11-09","items":[{"id":"W4-L1","kind":"mcq","stem":"What is the talk mainly about?","options":["a) robots on Mars","b) what Mars is like and why it is cold","c) the moons of Earth","d) how to travel to Mars"],"target_id":"A-T1-TEXT-L"},{"id":"W4-L2","kind":"short","stem":"Why does Mars look red?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W4-L3","kind":"short","stem":"Give one reason why Mars is cold.","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W4-L4","kind":"short","stem":"How long is a day on Mars?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W4-L5","kind":"short","stem":"How many moons does Mars have?","options":[],"target_id":"A-T1-TEXT-L"},{"id":"W4-L6","kind":"open","stem":"If Mars had a thick atmosphere like Earth, would it be warmer or colder? Why?","options":[],"target_id":"A-T2-INFER-L"}],"self_check_vi":[]},{"step_no":3,"activity_type":"ACT-SPEAK-LIVE","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Look at the NASA photos of Venus and Mars.","time_min":24,"planned_date":"2026-11-09","items":[],"self_check_vi":[]},{"step_no":4,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["A-T1-TEXT-R"],"prompt_en":"Read the text once, then answer. You may look back at the text.","time_min":25,"planned_date":"2026-11-10","items":[{"id":"W4-R1","kind":"mcq","stem":"What is the text mainly about?","options":["a) why Venus is so hot and what it is like","b) why Mercury is the hottest planet","c) how to visit Venus","d) the moons of Venus"],"target_id":"A-T1-TEXT-R"},{"id":"W4-R2","kind":"short","stem":"Why do people call Venus \"Earth's twin\"?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W4-R3","kind":"short","stem":"What is the air on Venus mostly made of?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W4-R4","kind":"short","stem":"Why does Venus stay so hot?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W4-R5","kind":"short","stem":"What are the clouds on Venus made of?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W4-R6","kind":"short","stem":"Which is longer on Venus: a day or a year?","options":[],"target_id":"A-T1-TEXT-R"},{"id":"W4-R7","kind":"open","stem":"Mercury is closer to the Sun than Venus. Why is this information in the text? What does it show?","options":[],"target_id":"A-T2-INFER-R"},{"id":"W4-R8","kind":"short","stem":"\"This thick air traps the heat.\" What does 'traps' mean?","options":[],"target_id":"A-T2-INFER-R"}],"self_check_vi":[]},{"step_no":5,"activity_type":"ACT-CANVAS-BASIC","mode":"PRACTICE","purpose":[],"target_ids":["A-T9-COMPARE"],"prompt_en":"Fill in the table (order from the Sun, size, temperature, air, moons). Main idea: Venus and Mars are both..., but... Why: [Venus is hot because...] [Mars is cold because...]. Example: 'If you stood on Venus,...' or 'On Mars, at night,...'","time_min":14,"planned_date":"2026-11-11","items":[{"id":"W4-CV","kind":"open","stem":"Fill in the comparison table.","options":[],"target_id":"A-T9-COMPARE"}],"self_check_vi":[]},{"step_no":6,"activity_type":"ACT-SPEAK-MONO","mode":"PRACTICE","purpose":[],"target_ids":["A-L3-CAUSE-S","A-L2-CHUNKS"],"prompt_en":"Mercury is closer to the Sun than Venus. So why is Venus hotter? - Mercury is..., but Venus is... / The atmosphere on Venus is..., and it is mostly... / This thick air..., like... / As a result,... (45-60 seconds)","time_min":12,"planned_date":"2026-11-11","items":[],"self_check_vi":[]},{"step_no":7,"activity_type":"ACT-WRITE","mode":"PRACTICE","purpose":[],"target_ids":["A-L3-CAUSE-W","A-L2-CHUNKS"],"prompt_en":"Why is Mars so cold? - Mars is colder than Earth for two reasons. First, Mars is..., so... / Second, its atmosphere is..., so... / That's why... (50-70 words)","time_min":18,"planned_date":"2026-11-12","items":[],"self_check_vi":[]},{"step_no":8,"activity_type":"ACT-SELF-REVIEW","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Check your own writing.","time_min":7,"planned_date":"2026-11-12","items":[],"self_check_vi":["Bạn đã nói được hai lý do vì sao Sao Hỏa lạnh chưa?","Bạn đã dùng 2 từ nối khác nhau và 4 từ mới chưa?"]},{"step_no":9,"activity_type":"ACT-SPEAK-MONO","mode":"INDEPENDENT_CHECK","purpose":["delayed_check","checkpoint"],"target_ids":["A-L3-CAUSE-S","A-L4-PROCESS-S","A-T4-CAUSE"],"prompt_en":"A younger child asks you: 'Where does rain come from?' Explain it simply, step by step. (30 seconds to think, no notes. Speak 60-90 seconds.)","time_min":7,"planned_date":"2026-11-13","items":[{"id":"W4-WATDEL","kind":"open","stem":"A younger child asks you: 'Where does rain come from?' Explain it simply, step by step.","options":[],"target_id":"A-L3-CAUSE-S"}],"self_check_vi":[]},{"step_no":10,"activity_type":"ACT-SPEAK-MONO","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-L3-CAUSE-S","A-T4-CAUSE","A-L2-CHUNKS","A-T7-OPINION"],"prompt_en":"Venus or Mars: which planet would be harder for astronauts to visit? Say which one you choose. Give two reasons and an example. Explain why that planet is so hot or so cold. (30 seconds to think. Speak 60-90 seconds.)","time_min":7,"planned_date":"2026-11-13","items":[{"id":"W4-SIC","kind":"open","stem":"Venus or Mars: which planet would be harder for astronauts to visit? Choose one, give two reasons and an example, and explain why that planet is so hot or so cold.","options":[],"target_id":"A-L3-CAUSE-S"}],"self_check_vi":[]},{"step_no":11,"activity_type":"ACT-SPEAK-LIVE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-X1-TURN","A-L2-COMPENSATE-S"],"prompt_en":"Choose one picture. It must be something you know how to use, but you do not know its English name. Tell me about it: what it looks like, what we use it for, and how you use it. (30 seconds to think, no writing. Speak 60-90 seconds.)","time_min":4,"planned_date":"2026-11-13","items":[{"id":"W4-LIVE","kind":"open","stem":"Choose one picture and tell me about it.","options":[],"target_id":"A-X1-TURN"}],"self_check_vi":[]},{"step_no":12,"activity_type":"ACT-SPEAK-LIVE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-L8-EXCHANGE-S"],"prompt_en":"I am an astronaut. I have just come back from space. Ask me at least two questions. (Then the tutor asks: Would you like to go to space one day?)","time_min":3,"planned_date":"2026-11-13","items":[{"id":"W4-INT","kind":"open","stem":"Ask the astronaut at least two questions.","options":[],"target_id":"A-L8-EXCHANGE-S"}],"self_check_vi":[]},{"step_no":13,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-L3-CAUSE-W","A-L3-PARA-W","A-T4-CAUSE","A-L2-CHUNKS"],"prompt_en":"Compare Venus and Mars in one paragraph (80-120 words). How are they the same, and how are they different? Explain why Venus is much hotter than Mars. (20 minutes.)","time_min":20,"planned_date":"2026-11-13","items":[{"id":"W4-WIC","kind":"open","stem":"Compare Venus and Mars in one paragraph.","options":[],"target_id":"A-L3-CAUSE-W"}],"self_check_vi":[]},{"step_no":14,"activity_type":"ACT-SELF-REVIEW","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["A-A1-SELFASSESS"],"prompt_en":"Before you hear any feedback, check your own paragraph.","time_min":3,"planned_date":"2026-11-13","items":[],"self_check_vi":["Khi so sánh, bạn đã nói cùng một điểm cho cả hai hành tinh chưa?","Bạn đã giải thích vì sao Sao Kim nóng hơn chưa?","Bạn đã dùng 2 từ nối khác nhau và 4 từ mới chưa?","Một điều mình làm tốt: ______","Một điều mình muốn sửa: ______"]},{"step_no":15,"activity_type":"ACT-REVISE","mode":"REVISION","purpose":[],"target_ids":["A-A3-REDRAFT"],"prompt_en":"Read each hint, fix your paragraph, underline what you changed, and write 'Mình đã đổi ... thành ... vì ...'.","time_min":15,"planned_date":"2026-11-13","items":[],"self_check_vi":[]}],"sources":[{"id":"A-W4-PLANETS-S1","version":1,"title":"Venus: Earth's Hot Twin (bài đọc PLA-R)","modality":"text","url":null},{"id":"A-W4-PLANETS-S2","version":1,"title":"Mars (bài nghe PLA-L, file A_PLA_L)","modality":"audio","url":null}]}]$j$::jsonb) as r
on conflict (id, version) do nothing;

insert into english.template_item_keys(template_id, template_version, item_id, step_no, kind, answer, explanation_vi)
select 'A-W4-PLANETS', 1, r->>'item_id', (r->>'step_no')::int, r->>'kind', r->>'answer', r->>'explanation_vi'
from jsonb_array_elements($j$[{"step_no":1,"item_id":"step-1:note","kind":"note","answer":null,"explanation_vi":"T2 9/11 (8') - Câu hỏi lớn. Mẹo nói tiếp khi quên từ."},{"step_no":2,"item_id":"W4-L1","kind":"answer","answer":"b","explanation_vi":"Ý chính (c1)."},{"step_no":2,"item_id":"W4-L2","kind":"sealed","answer":"Its rocks and dust have iron that has rusted.","explanation_vi":"Chi tiết 1/4 (nhân quả)."},{"step_no":2,"item_id":"W4-L3","kind":"sealed","answer":"It is farther from the Sun / its atmosphere is thin, so the heat escapes (một trong hai).","explanation_vi":"Chi tiết 2/4."},{"step_no":2,"item_id":"W4-L4","kind":"sealed","answer":"About 24 and a half hours. Chấp nhận 24-25 giờ.","explanation_vi":"Chi tiết 3/4."},{"step_no":2,"item_id":"W4-L5","kind":"sealed","answer":"Two (Phobos and Deimos).","explanation_vi":"Chi tiết 4/4. Cần >= 3/4."},{"step_no":2,"item_id":"W4-L6","kind":"sealed","answer":"Warmer - thick air holds the heat, so it cannot escape easily.","explanation_vi":"CHẨN ĐOÁN (suy luận)."},{"step_no":2,"item_id":"step-2:note","kind":"note","answer":null,"explanation_vi":"T2 9/11 (13') - Bài nghe về Sao Hỏa làm TRONG buổi cô. Không xem chữ."},{"step_no":3,"item_id":"step-3:note","kind":"note","answer":null,"explanation_vi":"T2 9/11 (12' + 8' + 4') - Chiếu ảnh NASA, giao việc. KHÔNG phát 8 cụm từ ở T2. KHÔNG giải thích trước câu 'If you stood on Venus...' vì bài đọc T3 là bài tự làm (đã thêm chú thích trong bài)."},{"step_no":4,"item_id":"W4-R1","kind":"answer","answer":"a","explanation_vi":"Ý chính (c1)."},{"step_no":4,"item_id":"W4-R2","kind":"sealed","answer":"It is almost the same size as Earth (and comes close to Earth).","explanation_vi":"Chi tiết 1/5."},{"step_no":4,"item_id":"W4-R3","kind":"sealed","answer":"Carbon dioxide.","explanation_vi":"Chi tiết 2/5."},{"step_no":4,"item_id":"W4-R4","kind":"sealed","answer":"The thick air traps the heat; the heat cannot escape.","explanation_vi":"Chi tiết 3/5 (nhân quả)."},{"step_no":4,"item_id":"W4-R5","kind":"sealed","answer":"Acid.","explanation_vi":"Chi tiết 4/5."},{"step_no":4,"item_id":"W4-R6","kind":"sealed","answer":"A day.","explanation_vi":"Chi tiết 5/5. \"Ngày\" = một vòng quay quanh trục (243 ngày Trái Đất) so với một năm (225 ngày) theo NASA. Cần >= 4/5."},{"step_no":4,"item_id":"W4-R7","kind":"sealed","answer":"Khoảng cách tới Mặt Trời không phải lý do chính; lý do chính là bầu khí quyển dày giữ nhiệt ('Why? The answer is its atmosphere').","explanation_vi":"CHẨN ĐOÁN (mục đích người viết). Câu trừu tượng với lớp 6, chỉ chẩn đoán."},{"step_no":4,"item_id":"W4-R8","kind":"sealed","answer":"Keeps it in / does not let it go out (giữ lại).","explanation_vi":"CHẨN ĐOÁN (nghĩa từ)."},{"step_no":4,"item_id":"step-4:note","kind":"note","answer":null,"explanation_vi":"T3 10/11 (18' + 7') - Bài đọc về Sao Kim ở nhà (18'). CUỐI T3, sau khi nộp bài đọc: phát 8 cụm từ + thẻ từ (7'). 8 cụm từ: planet = hành tinh · atmosphere = bầu khí quyển · carbon dioxide = khí CO2 · trap heat = giữ nhiệt lại · thick / thin = dày / mỏng · surface = bề mặt · far from the Sun = xa Mặt Trời · while = trong khi (để so sánh)."},{"step_no":5,"item_id":"W4-CV","kind":"sealed","answer":"Order 2 / 4; size almost Earth / about half; temperature ~467 C / from ~20 C to ~-150 C; air thick, mostly CO2 / thin; moons 0 / 2.","explanation_vi":"Tùy chọn."},{"step_no":5,"item_id":"step-5:note","kind":"note","answer":null,"explanation_vi":"T4 11/11 (14') - Canvas so sánh; được xem lại bài đọc và nghe lại bài Sao Hỏa. Đáp án bảng: thứ tự 2 / 4; gần bằng Trái Đất / khoảng một nửa; ~467 độ C, nóng nhất / lạnh, từ ~20 xuống ~-150 độ C; dày, chủ yếu CO2 / mỏng; 0 mặt trăng / 2 (Phobos, Deimos). A-T9-COMPARE ngoài bộ 12, tùy chọn."},{"step_no":6,"item_id":"step-6:note","kind":"note","answer":null,"explanation_vi":"T4 11/11 (12')."},{"step_no":7,"item_id":"step-7:note","kind":"note","answer":null,"explanation_vi":"T5 12/11 (18')."},{"step_no":8,"item_id":"step-8:note","kind":"note","answer":null,"explanation_vi":"T5 12/11 (5' + 2')."},{"step_no":9,"item_id":"W4-WATDEL","kind":"sealed","answer":"Mặt Trời làm nóng nước -> nước bốc hơi thành hơi nước -> hơi nước bay lên, gặp lạnh -> ngưng tụ thành giọt nhỏ -> mây -> giọt nhập lại, nặng -> mưa -> sông, biển, đất -> lặp lại. Cốc nước đá = bước ngưng tụ.","explanation_vi":"A-L3-CAUSE-S; A-L4-PROCESS-S; A-T4-CAUSE."},{"step_no":9,"item_id":"step-9:note","kind":"note","answer":null,"explanation_vi":"T6 13/11, LÀM ĐẦU TIÊN (7') - Bài ôn nước WAT-DEL. 13/11 - 30/10 = 14 ngày. last_practice_date = 2026-10-30. Chỉ làm nếu Sổ tiếp xúc không ghi lần nào gặp nội dung nước/mây/mưa từ 31/10."},{"step_no":10,"item_id":"W4-SIC","kind":"sealed","answer":"Không có đáp án đúng/sai về hành tinh. Phần giải thích: Sao Kim nóng vì không khí dày chủ yếu CO2 giữ nhiệt; Sao Hỏa lạnh vì xa Mặt Trời và khí quyển mỏng nên nhiệt thoát ra.","explanation_vi":"A-T7-OPINION (c1-c3); A-L3-CAUSE-S (>= 2 loại từ nối, đúng chiều); A-T4-CAUSE (>= 2 liên kết nhân quả nối thành chuỗi); A-L2-CHUNKS (>= 4 trong 8 cụm từ)."},{"step_no":10,"item_id":"step-10:note","kind":"note","answer":null,"explanation_vi":"T6 13/11 (7') - Nói tự làm (PLA-SIC), ghi âm, ghi activity_type = ACT-SPEAK-MONO. Tuần 4 ý kiến nằm trong bài này (không có bước OP riêng): chấm Nêu ý kiến (c1 quan điểm rõ, c2 >= 2 lý do, c3 >= 1 ví dụ) cùng Nói vì sao-nên và Chuỗi nguyên nhân (phần 'explain why hot/cold'). Không có đáp án đúng/sai: chọn Sao Hỏa vẫn hợp lệ nếu lý do liên quan. Giải thích một quá trình khi nói = NULL."},{"step_no":11,"item_id":"W4-LIVE","kind":"sealed","answer":"Không có đáp án mẫu. Cô ghi: vật An chọn, từ An chưa biết, cách An diễn đạt vòng (a thing that..., it is like...), có chuyển sang tiếng Việt không.","explanation_vi":"A-X1-TURN (c1 >= 60 giây; c2 <= 3 lần ngừng dài; c3 nói lại câu) và A-L2-COMPENSATE-S (c1 >= 1 lần diễn đạt vòng thành công bằng tiếng Anh; c2 <= 1 lần chuyển sang tiếng Việt), hoặc NULL."},{"step_no":11,"item_id":"step-11:note","kind":"note","answer":null,"explanation_vi":"T6 13/11 (4') - Lượt nói trực tiếp (kit mục 3.0, \"Thử thách thiếu từ\"). Cô đưa 3 ảnh: telescope (kính thiên văn) · binoculars (ống nhòm) · compass (la bàn). Cô không nói tên tiếng Anh trước T6; cô chỉ nói \"Bắt đầu nhé\" / \"Còn 30 giây\", không nhắc \"giải thích cách khác\". Ghi activity_type = ACT-SPEAK-LIVE, context_topic = lab-tools, chỉ cô chấm; cô bấm giờ (duration_s; c1 Nói trôi chảy cần >= 60 giây). Nói trôi chảy: c1 >= 60 giây, c2 <= 3 lần ngừng > 3 giây, c3 nói lại câu thay vì bỏ dở. Xoay xở khi thiếu từ: cô xác nhận có chỗ thiếu từ thật; An biết tên cả 3 vật (đổi bộ ảnh) hoặc không có chỗ thiếu thật => NULL, đó là kết quả hợp lệ."},{"step_no":12,"item_id":"W4-INT","kind":"sealed","answer":"Không có đáp án mẫu; ghi số câu hỏi An đặt và dạng câu hỏi.","explanation_vi":"Chẩn đoán trao đổi hai chiều."},{"step_no":12,"item_id":"step-12:note","kind":"note","answer":null,"explanation_vi":"T6 13/11 (3') - An phỏng vấn cô (PLA-INT): ghi việc An hỏi; A-L8-EXCHANGE-S ngoài bộ 12, chẩn đoán. Không chấm ý kiến lần hai (đã chấm ở PLA-SIC)."},{"step_no":13,"item_id":"W4-WIC","kind":"sealed","answer":"Cùng một điểm cho cả hai hành tinh; giải thích Sao Kim nóng vì khí quyển dày giữ nhiệt.","explanation_vi":"A-L3-CAUSE-W; A-L3-PARA-W; A-T4-CAUSE; A-L2-CHUNKS."},{"step_no":13,"item_id":"step-13:note","kind":"note","answer":null,"explanation_vi":"T6 13/11 (20') - Viết tự làm. Đề 80-120 từ. Dùng thì quá khứ: không ghi. A-L1-COMP-W và A-T9-COMPARE ngoài bộ 12, tùy chọn."},{"step_no":14,"item_id":"step-14:note","kind":"note","answer":null,"explanation_vi":"T6 13/11 (3'). Tự kiểm: 1 điểm giống và khác của hai hành tinh; 2 giải thích vì sao Sao Kim nóng hơn Sao Hỏa; 3 nói cùng một điểm cho cả hai hành tinh."},{"step_no":15,"item_id":"step-15:note","kind":"note","answer":null,"explanation_vi":"T6 13/11 (7' + 15') - Thêm: kẻ hai cột Venus | Mars; mỗi câu so sánh đã có đủ cả hai cột chưa? Sau giờ: cô chấm lại mù 6 bài."}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'A-W4-PLANETS' and it.version = 1 and it.published_at is not null)
on conflict (template_id, template_version, item_id) do nothing;

update english.inquiry_templates set status = 'published', published_at = now()
where id = 'A-W4-PLANETS' and version = 1 and published_at is null;

-- Inquiry template B-W0-BASELINE v1 (published after its sources and answer keys are in)
insert into english.sources(id, version, title, url, author, rights_note, modality, body, source_hash)
select r->>'id', (r->>'version')::int, r->>'title', r->>'url', r->>'author', r->>'rights_note', r->>'modality', r->>'body', r->>'source_hash'
from jsonb_array_elements($j$[{"id":"B-W0-BASELINE-S1","version":1,"title":"Volunteering (cloze passage, MINI-20 Q10-15)","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"Volunteering is becoming increasingly (10) ______ among teenagers in Vietnam's big cities. Some students help at local libraries, (11) ______ others prefer to join clean-up days in parks and along rivers. Many volunteers say the work gives them a real sense of (12) ______ that they do not always get from tests and marks. They also learn practical skills, such as working in a team and talking to people of different ages. One student explained that she used to be very shy in class, but after a few months at a children's reading club she felt much more (13) ______. Schools have noticed the trend, and some now give certificates to students who volunteer regularly throughout the year. However, teachers warn that volunteering should not take too much time away (14) ______ sleep or homework. A sensible plan, they suggest, is to choose one activity and (15) ______ it seriously, rather than trying to join everything at once.","source_hash":"863edd20e14cb38f273bfafd2751674c66f9152c6c2a66f9bfef69d4e8be4e50"},{"id":"B-W0-BASELINE-S2","version":1,"title":"Rooftop garden (reading, MINI-20 Q16-17)","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"Two years ago, the students of a city secondary school turned the empty roof of their building into a small vegetable garden. At first, the project was meant to be a one-term science activity. However, the garden soon became a popular place to spend break time, and a group of students offered to water the plants during the summer holiday. Today, the school kitchen uses some of the vegetables, and younger classes visit the roof to learn how plants grow. The teacher who started the project says the biggest surprise was not the harvest but the number of students who kept coming back without being asked.","source_hash":"e29a28c1b28b8c59d24198bd4b27188e2c2bf70adf5840c4515f04270c6254f0"},{"id":"B-W0-BASELINE-S3","version":1,"title":"Let Us Sleep: Why Our School Day Should Start Later","url":null,"author":"Imagined student writer (invented)","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"¶1 Every morning at 6:15, my alarm goes off, and every morning I make the same promise: tonight I will go to bed earlier. I never do. I am not lazy, and neither are my classmates. The problem is that our school day starts at 7:00, which is simply too early for teenagers. I believe our school should move the start of lessons to 8:00.\n\n¶2 My first reason is health. Doctors often explain that during the teenage years the body clock shifts, so many teenagers do not feel sleepy until late in the evening. If we have to get up before 6:30, we cannot get the eight to ten hours of sleep that we need. Last month, the student council asked 200 students in our school about their sleep. Sixty-two per cent said they slept fewer than seven hours on school nights.\n\n¶3 My second reason is learning. Anyone who has visited a first-period class knows what I mean: half the room is yawning, and the other half is staring at the board without seeing it. A tired student is not a stupid student, but he or she is a slower one. Starting an hour later would turn that wasted first lesson into a useful one.\n\n¶4 Third, a later start would make mornings safer. At the moment, many of us cycle to school in the dark during the winter months, when the roads are busy with trucks.\n\n¶5 Some people argue that a later start means a later finish, so students would have less time for homework and extra classes. That is true, but it misses the point. An extra hour in the afternoon is worth much less than an extra hour of sleep. In any case, students who sleep longer will be more alert in the evening too, so they will finish their homework faster.\n\n¶6 Changing the timetable will not be easy. Teachers, parents and bus drivers would all need to adjust. But if we really care about students, the question is not whether we can afford to change. It is whether we can afford not to.","source_hash":"3b93acddb3648179d0ff91e441517fe8d988ceab72dd9845ff4ea0e7c3e2977c"},{"id":"B-W0-BASELINE-S4","version":1,"title":"Lunchtime library: hypothetical data","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"HYPOTHETICAL DATA, invented for practice. These are not real results.\nA secondary school opened its library at lunchtime for one term (September–December), for class 9A only. Class 9B kept the old timetable (library open only after school).\n\n| | 9A (lunchtime library) | 9B (no change) |\n|---|---|---|\n| Students in class | 40 | 38 |\n| Books borrowed per student per month, August | 0.8 | 0.9 |\n| Books borrowed per student per month, December | 1.9 | 1.0 |\n| Students who said \"I enjoy reading more now\" (December) | 22 of 40 | 9 of 38 |\n| End-of-term reading test, class average (out of 10) | 7.1 | 7.0 |\n\n*Note: in October, 9A's English teacher also started a weekly book club.*\n\nQuestion: Did opening the library at lunchtime make students in 9A read more and read better?\n\nFill in the four boxes in English (1–3 sentences each):\n1. Claim: your answer to the question.\n2. Evidence: at least two numbers from the table that support or challenge your claim.\n3. Limitation: at least one reason why this data cannot fully answer the question.\n4. Conditional conclusion: how sure are you? What would make you more (or less) sure?","source_hash":"1722c65424fb71ffc23454c6e664ec49c40444ce427cf25d8baa799de00a1e96"},{"id":"B-W0-BASELINE-S5","version":1,"title":"Water refill stations (listening script)","url":null,"author":"Imagined student-council speaker (invented)","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào. Phát bằng giọng đọc máy cố định trên máy phụ huynh; không ghi âm giọng Nguyên.","modality":"audio","body":null,"source_hash":"714268f2ffe84733447daf9e0d4f25fee0e33b7487dc86fc3c46c5c1c6a36732"},{"id":"B-W0-BASELINE-S6","version":1,"title":"The planning fallacy","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào. KHÔNG cho thầy/cô xem trước buổi (FIXLIST #1).","modality":"text","body":"Most people are surprisingly bad at predicting how long their own tasks will take. Psychologists call this the \"planning fallacy\". When we plan, we tend to imagine the best version of the task: we picture ourselves working steadily, with no interruptions, no mistakes and no tiredness. We rarely think about the things that went wrong last time. Interestingly, when we predict how long other people's tasks will take, we tend to be less optimistic, because we think about what actually happened to them before rather than about their hopes. One way to reduce the planning fallacy is to ask, \"How long did a similar task actually take me last time?\" and to use that answer, not your hopes, as a starting point. Another tip is to break a big task into smaller steps and estimate each one, which makes it harder to forget parts of the work.","source_hash":"74d6229276236524d1ab3b9173e4e940fc57ee394ce4577a0a1af12c15e8bbbd"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'B-W0-BASELINE' and it.version = 1 and it.published_at is not null)
on conflict (id, version) do nothing;

insert into english.source_transcripts(source_id, source_version, transcript)
select r->>'id', (r->>'version')::int, r->>'transcript'
from jsonb_array_elements($j$[{"id":"B-W0-BASELINE-S5","version":1,"transcript":"Good morning, everyone. I'm speaking on behalf of the student council about our proposal to put water refill stations in the school. At the moment, our canteen sells about three hundred plastic bottles of water every day, and most of them end up in the bin after one use. We think there is a better way.\nOur plan is simple. The school would put three refill stations in the main building, and every student would be asked to bring a reusable bottle. The stations would cost money at the start, but the canteen would no longer need to order bottled water, so the cost could be recovered in about two years.\nOf course, there are some concerns. Some parents have asked whether the water would be safe to drink. That's a fair question, and we think the filters should be tested every term, with the results posted on the notice board. Others worry that younger students will forget their bottles. For them, the canteen could keep a small supply of paper cups.\nWe are not saying this will solve every environmental problem. But it is a practical step, and we'd like to try it for one term and then review it together."}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'B-W0-BASELINE' and it.version = 1 and it.published_at is not null)
on conflict (source_id, source_version) do nothing;

update english.sources set published_at = now()
where version = 1 and id in ('B-W0-BASELINE-S1', 'B-W0-BASELINE-S2', 'B-W0-BASELINE-S3', 'B-W0-BASELINE-S4', 'B-W0-BASELINE-S5', 'B-W0-BASELINE-S6') and published_at is null;

insert into english.inquiry_templates(id, version, track_id, title_vi, big_question_en, big_question_vi, week, date_from, date_to, domain_bucket, target_ids, steps, sources, catalogue_version, status, source_hash)
select r->>'id', (r->>'version')::int, r->>'track_id', r->>'title_vi', r->>'big_question_en', r->>'big_question_vi', (r->>'week')::int,
  (r->>'date_from')::date, (r->>'date_to')::date, r->>'domain_bucket',
  array(select e from jsonb_array_elements_text(r->'target_ids') with ordinality as t(e, n) order by n), r->'steps', r->'sources', '0.2.1-draft', 'draft', 'c9d6b784dc3bb12f3c7c8fae11b5a54036b74877b9d8acde40968c6f7807f750'
from jsonb_array_elements($j$[{"id":"B-W0-BASELINE","version":1,"track_id":"B","title_vi":"Baseline B v0.2.1 (2 buổi × 60 phút)","big_question_en":"Baseline: where does Nguyên start on each B-v1 target?","big_question_vi":"Hồ sơ xuất phát cho từng kỹ năng (không tính vào \"Tự làm được\")","week":0,"date_from":"2026-10-17","date_to":"2026-10-18","domain_bucket":"society","target_ids":["B-T1-EXAM-R","B-L2-CLOZE","B-T1-ARG-R","B-T2-ASSUME-R","B-T5-DATAOP","B-T11-QUALIFY","B-L1-COMPLEX-W","B-L2-PRECISE","B-L4-EXPLAIN-S","AGG-B-EXAM-MOCK"],"steps":[{"step_no":1,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":["baseline"],"target_ids":["AGG-B-EXAM-MOCK","B-L2-CLOZE"],"prompt_en":"Choose the best answer (A, B, C or D). 25 minutes. No dictionary.","time_min":25,"planned_date":"2026-10-17","items":[{"id":"BL-a01","kind":"mcq","stem":"Choose the word whose underlined part is pronounced differently: h[ea]lthy / br[ea]kfast / h[ea]vy / m[ea]ning","options":["healthy","breakfast","heavy","meaning"],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a02","kind":"mcq","stem":"Choose the word whose underlined part is pronounced differently: watch[ed] / hop[ed] / decid[ed] / laugh[ed]","options":["watched","hoped","decided","laughed"],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a03","kind":"mcq","stem":"Choose the word that has a different stress pattern from the others.","options":["reply","student","village","study"],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a04","kind":"mcq","stem":"Choose the word that has a different stress pattern from the others.","options":["important","family","computer","remember"],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a05","kind":"mcq","stem":"If I ______ more free time, I would join the school debate club.","options":["have","will have","would have","had"],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a06","kind":"mcq","stem":"The library ______ in 1998 is going to be repainted next month.","options":["built","building","was built","which built"],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a07","kind":"mcq","stem":"The class trip was ______ because of the heavy rain.","options":["taken after","called off","looked up","given in"],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a08","kind":"mcq","stem":"Mai: \"Would you mind if I opened the window?\" – Lan: \"______\"","options":["Yes, I'd love to.","You're welcome.","No, go ahead.","Never mind."],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a09","kind":"mcq","stem":"This notice is on the door of the school library: SILENT STUDY ZONE – Phones on silent. Group discussions in Room 2 only.","options":["Students may not use phones anywhere in the library.","Room 2 is closed for group discussions.","Students must leave their phones at the entrance.","Students who want to work in groups should go to Room 2."],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a10","kind":"word_form","stem":"Gap (10)","options":["popularity","popularly","popular","populate"],"target_id":"B-L2-CLOZE"},{"id":"BL-a11","kind":"gap","stem":"Gap (11)","options":["while","because","so","unless"],"target_id":"B-L2-CLOZE"},{"id":"BL-a12","kind":"word_form","stem":"Gap (12)","options":["achieve","achievement","achieving","achievable"],"target_id":"B-L2-CLOZE"},{"id":"BL-a13","kind":"word_form","stem":"Gap (13)","options":["confidence","confidently","confide","confident"],"target_id":"B-L2-CLOZE"},{"id":"BL-a14","kind":"gap","stem":"Gap (14)","options":["of","with","from","at"],"target_id":"B-L2-CLOZE"},{"id":"BL-a15","kind":"gap","stem":"Gap (15)","options":["take","make","hold","get"],"target_id":"B-L2-CLOZE"},{"id":"BL-a16","kind":"mcq","stem":"What is the passage mainly about?","options":["how to grow vegetables on a roof","a short science activity that grew into a lasting school project","why the school kitchen needs fresh vegetables","a teacher's plan to change break time"],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a17","kind":"mcq","stem":"What does the teacher's comment in the last sentence suggest?","options":["The garden produced fewer vegetables than expected.","Students were required to visit the garden every week.","The project will probably end soon.","The students' willingness to come back on their own impressed the teacher more than the harvest."],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a18","kind":"mcq","stem":"Choose the sentence closest in meaning: I haven't seen my cousin for three years.","options":["I saw my cousin three years.","I didn't see my cousin three years ago.","I last saw my cousin three years ago.","It's three years when I saw my cousin."],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a19","kind":"mcq","stem":"Choose the sentence closest in meaning: It's a pity I can't speak Japanese.","options":["I wish I could speak Japanese.","I wish I can speak Japanese.","If only I couldn't speak Japanese.","I wish I didn't speak Japanese."],"target_id":"AGG-B-EXAM-MOCK"},{"id":"BL-a20","kind":"mcq","stem":"Choose the best order: a. First, it saves time, because students do not have to wait for the bus. b. Many students in my class now cycle to school. c. Second, it is good exercise at the start of the day. d. There are two main reasons for this.","options":["d–b–a–c","b–d–a–c","b–a–d–c","b–d–c–a"],"target_id":"AGG-B-EXAM-MOCK"}],"self_check_vi":[]},{"step_no":2,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":["baseline"],"target_ids":["B-T1-EXAM-R","B-T1-ARG-R","B-T2-ASSUME-R","B-T5-DATAOP"],"prompt_en":"No dictionary. For questions 3, 4 and 6, write the paragraph number (¶) and the first few words of the sentence that supports your answer. Part 2: answer in English (short answers are fine).","time_min":22,"planned_date":"2026-10-17","items":[{"id":"BL-b01","kind":"mcq","stem":"What is the writer's main purpose?","options":["to describe a typical morning at school","to explain how the body clock works","to persuade readers that the school day should start later","to complain about homework"],"target_id":"B-T1-EXAM-R"},{"id":"BL-b02","kind":"mcq","stem":"According to paragraph 2, which is true about the student council's survey?","options":["200 students slept fewer than seven hours on school nights.","More than half of the students asked slept fewer than seven hours on school nights.","62 students slept fewer than seven hours on school nights.","Most students slept eight to ten hours."],"target_id":"B-T1-EXAM-R"},{"id":"BL-b03","kind":"mcq","stem":"The word \"alert\" in paragraph 5 is closest in meaning to ______. (Write ¶ + supporting sentence.)","options":["awake and able to think clearly","worried","sleepy","busy"],"target_id":"B-T1-EXAM-R"},{"id":"BL-b04","kind":"mcq","stem":"What does the writer imply in paragraph 3? (Write ¶ + supporting sentence.)","options":["Students in the first lesson are less intelligent.","Teachers should stop teaching in the first period.","Students yawn because the lessons are boring.","The first lesson is currently of little use to many students."],"target_id":"B-T1-EXAM-R"},{"id":"BL-b05","kind":"mcq","stem":"How does the writer respond to the opposing view in paragraph 5?","options":["The writer accepts it completely and changes position.","The writer admits part of it is true but argues that sleep matters more.","The writer ignores it.","The writer says it is not worth answering."],"target_id":"B-T1-EXAM-R"},{"id":"BL-b06","kind":"mcq","stem":"In the last paragraph, the writer suggests that ______. (Write ¶ + supporting sentence.)","options":["changing the timetable would be cheap and easy","bus drivers are against the change","keeping the current timetable also has a cost","teachers will refuse to adjust"],"target_id":"B-T1-EXAM-R"},{"id":"BL-b07","kind":"short","stem":"In one sentence, what is the writer's main claim?","options":[],"target_id":"B-T1-ARG-R"},{"id":"BL-b08","kind":"short","stem":"List three reasons the writer gives.","options":[],"target_id":"B-T1-ARG-R"},{"id":"BL-b09","kind":"open","stem":"The writer seems to take something for granted without saying it. Name one unstated assumption, and quote the words that show it.","options":[],"target_id":"B-T2-ASSUME-R"},{"id":"BL-b10i","kind":"mcq","stem":"\"Our school day starts at 7:00.\"","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"BL-b10ii","kind":"mcq","stem":"\"7:00 is simply too early for teenagers.\"","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"BL-b10iii","kind":"mcq","stem":"\"Last month, the student council asked 200 students in our school about their sleep.\"","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"BL-b10iv","kind":"mcq","stem":"\"Sixty-two per cent said they slept fewer than seven hours on school nights.\"","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"BL-b10v","kind":"mcq","stem":"\"A tired student is not a stupid student, but he or she is a slower one.\"","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"BL-b10vi","kind":"mcq","stem":"\"An extra hour in the afternoon is worth much less than an extra hour of sleep.\"","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"BL-b11","kind":"open","stem":"Choose two statements you marked C. For each, explain in 1-2 sentences why it is commentary, not data.","options":[],"target_id":"B-T5-DATAOP"}],"self_check_vi":[]},{"step_no":3,"activity_type":"ACT-CANVAS-ADV","mode":"INDEPENDENT_CHECK","purpose":["baseline"],"target_ids":["B-T11-QUALIFY"],"prompt_en":"Fill in the four boxes in English (1-3 sentences each): 1. Claim 2. Evidence (at least two numbers from the table) 3. Limitation 4. Conditional conclusion: how sure are you? What would make you more (or less) sure?","time_min":13,"planned_date":"2026-10-17","items":[{"id":"BL-f01","kind":"open","stem":"Did opening the library at lunchtime make students in 9A read more and read better? Fill in Claim / Evidence / Limitation / Conditional conclusion.","options":[],"target_id":"B-T11-QUALIFY"}],"self_check_vi":[]},{"step_no":4,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":["baseline"],"target_ids":[],"prompt_en":"Read the questions first (1 minute). You will hear the talk twice.","time_min":10,"planned_date":"2026-10-18","items":[{"id":"BL-c01","kind":"mcq","stem":"What is the speaker's main purpose?","options":["to complain about the canteen","to propose putting water refill stations in the school","to explain how water filters work","to ask students to buy more bottled water"],"target_id":null},{"id":"BL-c02","kind":"mcq","stem":"According to the speaker, how could the cost of the stations be recovered?","options":["by charging students for water","through parents' donations","because the canteen would no longer need to order bottled water","by selling reusable bottles"],"target_id":null},{"id":"BL-c03","kind":"short","stem":"What does the speaker suggest to deal with parents' worries about safety?","options":[],"target_id":null},{"id":"BL-c04","kind":"mcq","stem":"Which best describes the speaker's attitude to the plan?","options":["certain that it will solve all environmental problems","doubtful whether it is worth trying","angry with the parents who raised concerns","cautiously positive: a practical step to try and then review"],"target_id":null},{"id":"BL-c05","kind":"mcq","stem":"What can be inferred about the plan?","options":["The council is open to changing it after a trial.","It has already been approved by the school.","Younger students will not be allowed to use the stations.","The canteen will stop selling food."],"target_id":null}],"self_check_vi":[]},{"step_no":5,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":["baseline"],"target_ids":["B-L1-COMPLEX-W","B-L2-PRECISE"],"prompt_en":"Your school is thinking about replacing one written test per term in each subject with a group project. Do you think this is a good idea? Write 250-280 words. Give a clear opinion, at least two reasons with examples, and a short conclusion. No dictionary, no spell-check, no AI.","time_min":35,"planned_date":"2026-10-18","items":[],"self_check_vi":["Bài đã đủ 250 từ chưa?","Có vài câu phức với which, who, although, if… chưa?"]},{"step_no":6,"activity_type":"ACT-SPEAK-LIVE","mode":"INDEPENDENT_CHECK","purpose":["baseline"],"target_ids":["B-L4-EXPLAIN-S"],"prompt_en":"Read for 2 minutes, then turn the paper over. Explain the idea to your teacher, who has not read it, so that they can say it back to you in one sentence. Use at least one example from everyday life.","time_min":15,"planned_date":"2026-10-18","items":[{"id":"BL-e01","kind":"open","stem":"Tutor restates the main idea in one sentence; then compare with the key idea.","options":[],"target_id":"B-L4-EXPLAIN-S"}],"self_check_vi":[]}],"sources":[{"id":"B-W0-BASELINE-S1","version":1,"title":"Volunteering (cloze passage, MINI-20 Q10-15)","modality":"text","url":null},{"id":"B-W0-BASELINE-S2","version":1,"title":"Rooftop garden (reading, MINI-20 Q16-17)","modality":"text","url":null},{"id":"B-W0-BASELINE-S3","version":1,"title":"Let Us Sleep: Why Our School Day Should Start Later","modality":"text","url":null},{"id":"B-W0-BASELINE-S4","version":1,"title":"Lunchtime library: hypothetical data","modality":"text","url":null},{"id":"B-W0-BASELINE-S5","version":1,"title":"Water refill stations (listening script)","modality":"audio","url":null},{"id":"B-W0-BASELINE-S6","version":1,"title":"The planning fallacy","modality":"text","url":null}]}]$j$::jsonb) as r
on conflict (id, version) do nothing;

insert into english.template_item_keys(template_id, template_version, item_id, step_no, kind, answer, explanation_vi)
select 'B-W0-BASELINE', 1, r->>'item_id', (r->>'step_no')::int, r->>'kind', r->>'answer', r->>'explanation_vi'
from jsonb_array_elements($j$[{"step_no":1,"item_id":"BL-a01","kind":"answer","answer":"D","explanation_vi":"meaning /iː/, các từ còn lại /e/."},{"step_no":1,"item_id":"BL-a02","kind":"answer","answer":"C","explanation_vi":"decided /ɪd/, các từ còn lại /t/."},{"step_no":1,"item_id":"BL-a03","kind":"answer","answer":"A","explanation_vi":"reply nhấn âm 2, các từ còn lại âm 1."},{"step_no":1,"item_id":"BL-a04","kind":"answer","answer":"B","explanation_vi":"family nhấn âm 1, các từ còn lại âm 2."},{"step_no":1,"item_id":"BL-a05","kind":"answer","answer":"D","explanation_vi":"Câu điều kiện loại 2: If + quá khứ đơn, would + V."},{"step_no":1,"item_id":"BL-a06","kind":"answer","answer":"A","explanation_vi":"Rút gọn mệnh đề quan hệ bị động (which was built → built)."},{"step_no":1,"item_id":"BL-a07","kind":"answer","answer":"B","explanation_vi":"call off = hủy."},{"step_no":1,"item_id":"BL-a08","kind":"answer","answer":"C","explanation_vi":"Would you mind…? → \"No, go ahead\" là đồng ý."},{"step_no":1,"item_id":"BL-a09","kind":"answer","answer":"D","explanation_vi":"Thảo luận nhóm chỉ ở Room 2; điện thoại để im lặng chứ không bị cấm."},{"step_no":1,"item_id":"BL-a10","kind":"answer","answer":"C","explanation_vi":"increasingly + tính từ: popular."},{"step_no":1,"item_id":"BL-a11","kind":"answer","answer":"A","explanation_vi":"while nối hai ý đối lập (some… while others…)."},{"step_no":1,"item_id":"BL-a12","kind":"answer","answer":"B","explanation_vi":"a sense of + danh từ: achievement."},{"step_no":1,"item_id":"BL-a13","kind":"answer","answer":"D","explanation_vi":"felt (much more) + tính từ: confident."},{"step_no":1,"item_id":"BL-a14","kind":"answer","answer":"C","explanation_vi":"take time away from."},{"step_no":1,"item_id":"BL-a15","kind":"answer","answer":"A","explanation_vi":"take it seriously. (ĐÃ SỬA theo FIXLIST: phương án C cũ \"do\" bị thay bằng \"hold\" vì \"do it seriously\" cũng dùng được.)"},{"step_no":1,"item_id":"BL-a16","kind":"answer","answer":"B","explanation_vi":"Ý chính cả đoạn."},{"step_no":1,"item_id":"BL-a17","kind":"answer","answer":"D","explanation_vi":"\"not the harvest but… without being asked\"."},{"step_no":1,"item_id":"BL-a18","kind":"answer","answer":"C","explanation_vi":"Hiện tại hoàn thành + for → last + quá khứ + ago."},{"step_no":1,"item_id":"BL-a19","kind":"answer","answer":"A","explanation_vi":"It's a pity I can't → I wish I could."},{"step_no":1,"item_id":"BL-a20","kind":"answer","answer":"B","explanation_vi":"b (chủ đề) – d (hai lý do) – a (First) – c (Second)."},{"step_no":1,"item_id":"step-1:note","kind":"note","answer":null,"explanation_vi":"Thứ Bảy 17/10 · (a) Đề rút gọn 20 câu, phụ huynh bấm giờ. Ghi theo phần MINI-20: PRON 1-4 · VOCGRAM 5-7 · COMM 8 · CLOZE 10-15 + 20 · READ 9, 16, 17 · TRANS 18-19. B-L2-CLOZE chấm trên câu 10-15 (c1 ≥ 5/6; c2 dạng từ 10, 12, 13 ≥ 2/3)."},{"step_no":2,"item_id":"BL-b01","kind":"answer","answer":"C","explanation_vi":"Bài nghị luận đề xuất dời giờ học."},{"step_no":2,"item_id":"BL-b02","kind":"answer","answer":"B","explanation_vi":"62% của 200 (= 124 em) là hơn một nửa."},{"step_no":2,"item_id":"BL-b03","kind":"answer","answer":"A","explanation_vi":"Căn cứ ¶5 \"students who sleep longer will be more alert in the evening too, so they will finish their homework faster\"."},{"step_no":2,"item_id":"BL-b04","kind":"answer","answer":"D","explanation_vi":"Căn cứ ¶3 \"Starting an hour later would turn that wasted first lesson into a useful one\"."},{"step_no":2,"item_id":"BL-b05","kind":"answer","answer":"B","explanation_vi":"¶5 \"That is true, but it misses the point\". Dòng này cũng là c3 của B-T1-ARG-R (lập trường)."},{"step_no":2,"item_id":"BL-b06","kind":"answer","answer":"C","explanation_vi":"Căn cứ ¶6 \"whether we can afford not to\"."},{"step_no":2,"item_id":"BL-b07","kind":"sealed","answer":"The school should move the start of lessons from 7:00 to 8:00 (start later).","explanation_vi":"c1 của B-T1-ARG-R."},{"step_no":2,"item_id":"BL-b08","kind":"sealed","answer":"Health/sleep (¶2) · learning – tired students are slower, first lesson wasted (¶3) · safety – cycling in the dark (¶4).","explanation_vi":"Cần đủ 3 lý do (c2 của B-T1-ARG-R)."},{"step_no":2,"item_id":"BL-b09","kind":"sealed","answer":"Một trong: (i) dời giờ thì học sinh thực sự ngủ thêm, không thức khuya hơn (¶2 \"If we have to get up before 6:30…\", ¶5) · (ii) 200 em được hỏi đại diện cho cả trường (¶2 \"asked 200 students\") · (iii) điều thấy ở lớp mình đúng cho mọi lớp (¶1 \"neither are my classmates\", ¶3 \"Anyone who has visited…\") · (iv) với MỌI học sinh, giờ buổi chiều kém giá trị hơn giờ ngủ (¶5).","explanation_vi":"c1 giả định hợp lý; c2 trích đúng; c3 trình bày như điều người viết ngầm cho là đúng, không như điều bài nói ra. Với (iv): chỉ chấp nhận khi học sinh nêu phần NGẦM (áp dụng cho mọi học sinh), vì \"worth much less\" là điều bài đã nói thẳng."},{"step_no":2,"item_id":"BL-b10i","kind":"answer","answer":"A","explanation_vi":"Dữ liệu/bằng chứng (D)."},{"step_no":2,"item_id":"BL-b10ii","kind":"answer","answer":"B","explanation_vi":"Bình luận/diễn giải (C)."},{"step_no":2,"item_id":"BL-b10iii","kind":"answer","answer":"A","explanation_vi":"Dữ liệu/bằng chứng (D)."},{"step_no":2,"item_id":"BL-b10iv","kind":"answer","answer":"A","explanation_vi":"Dữ liệu/bằng chứng (D)."},{"step_no":2,"item_id":"BL-b10v","kind":"answer","answer":"B","explanation_vi":"Bình luận/diễn giải (C)."},{"step_no":2,"item_id":"BL-b10vi","kind":"answer","answer":"B","explanation_vi":"Bình luận/diễn giải (C)."},{"step_no":2,"item_id":"BL-b11","kind":"sealed","answer":"Ví dụ: (ii) là đánh giá (\"simply too early\"), không có số đo · (v) là khái quát/so sánh không dựa trên phép đo · (vi) là so sánh giá trị, tùy người nói.","explanation_vi":"c2 của B-T5-DATAOP: ≥ 2 giải thích đúng."},{"step_no":2,"item_id":"step-2:note","kind":"note","answer":null,"explanation_vi":"Thứ Bảy 17/10 · (b) Đọc bài nghị luận ≈ 345 từ: đọc 4' + 6 câu trắc nghiệm 8' + tự luận 10'. Văn bản ngắn hơn yêu cầu của B-T1-ARG-R: ghi notes \"văn bản ngắn hơn yêu cầu target\"."},{"step_no":3,"item_id":"BL-f01","kind":"sealed","answer":"Mượn sách 9A 0,8→1,9 trong khi 9B 0,9→1,0; thích đọc 22/40 so với 9/38; nhưng điểm đọc 7,1 so với 7,0. Giới hạn: câu lạc bộ sách cũng bắt đầu ở 9A (gây nhiễu), 1 lớp, 1 học kỳ, mượn chưa chắc là đọc, \"thích đọc\" là tự khai, không có điểm đọc đầu kỳ để so, tháng 8 có thể là kỳ nghỉ. Kết luận đạt: \"Có khả năng thư viện (có lẽ cùng CLB sách) làm 9A mượn sách nhiều hơn; chưa đủ bằng chứng rằng các em đọc giỏi hơn. Sẽ chắc hơn nếu lớp khác mở thư viện mà không có CLB sách và vẫn thấy kết quả tương tự.\"","explanation_vi":"c1 mức chắc chắn khớp bằng chứng; c2 có ≥ 1 điều kiện. \"Chưa đủ bằng chứng\" có lập luận vẫn đạt 3-4."},{"step_no":3,"item_id":"step-3:note","kind":"note","answer":null,"explanation_vi":"Thứ Bảy 17/10 · (f) Canvas trên số liệu giả định, 13 phút."},{"step_no":4,"item_id":"BL-c01","kind":"answer","answer":"B","explanation_vi":"Chẩn đoán, ngoài 12 kỹ năng."},{"step_no":4,"item_id":"BL-c02","kind":"answer","answer":"C","explanation_vi":null},{"step_no":4,"item_id":"BL-c03","kind":"sealed","answer":"Test the filters every term AND post the results on the notice board.","explanation_vi":"Cần đủ cả hai ý."},{"step_no":4,"item_id":"BL-c04","kind":"answer","answer":"D","explanation_vi":null},{"step_no":4,"item_id":"BL-c05","kind":"answer","answer":"A","explanation_vi":"\"try it for one term and then review it together\"."},{"step_no":4,"item_id":"step-4:note","kind":"note","answer":null,"explanation_vi":"Chủ nhật 18/10 (ở nhà) · (c) Nghe ≈ 200 từ, 2 lần, không mở lời bài. Chẩn đoán, nằm ngoài 12 kỹ năng: ghi auto_checks = n/5, để trống score."},{"step_no":5,"item_id":"step-5:note","kind":"note","answer":null,"explanation_vi":"Chủ nhật 18/10 · (d) Dàn ý 5' + viết 27' + đọc lại 3'. ĐÃ SỬA (FIXLIST #2): yêu cầu 250-280 từ (giữ 35 phút) để B-L1-COMPLEX-W, vốn chỉ chấm khi bài ≥ 250 từ, có cơ hội hợp lệ. B-T7-ARGUE để trống (không có nguồn)."},{"step_no":6,"item_id":"BL-e01","kind":"sealed","answer":"People usually underestimate how long their own tasks will take because they imagine an ideal version of the work and ignore past problems; they can plan better by using how long similar tasks actually took and by breaking tasks into steps.","explanation_vi":"c1 thầy/cô nhắc lại khớp ý chính; c2 có ≥ 1 ví dụ hoặc so sánh."},{"step_no":6,"item_id":"step-6:note","kind":"note","answer":null,"explanation_vi":"Chủ nhật 18/10, 20:30 trong buổi · (e) 15': đọc 2' + giải thích 2-3' + thầy/cô nhắc lại 1' + trao đổi 5' + ghi nhận xét 4'. Ý chính để đối chiếu (phụ huynh giữ trong phong bì, chỉ mở SAU khi thầy/cô nhắc lại): \"People usually underestimate how long their own tasks will take because they imagine an ideal version of the work and ignore past problems. They can plan better by basing estimates on how long similar tasks actually took, and by breaking tasks into steps.\" Baseline không tính vào \"Tự làm được\"."}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'B-W0-BASELINE' and it.version = 1 and it.published_at is not null)
on conflict (template_id, template_version, item_id) do nothing;

update english.inquiry_templates set status = 'published', published_at = now()
where id = 'B-W0-BASELINE' and version = 1 and published_at is null;

insert into english.schema_migrations(version) values ('0008') on conflict do nothing;
